L2_1.m_VoiceFileName = "TUTORIAL_VOICE_1"
L2_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L2_1.m_Talk_KOREA = "……가끔씩, 그런 생각을 해."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "……時々考えるの。"
L2_1.m_Talk_ENG = "... I often think of our fate."
L2_1.m_Talk_TWN = "……我時常會想，"
L2_1.m_Talk_THA = "... ฉันคิดเรื่องโชคชะตาของเราอยู่เสมอ"
L2_1.m_Talk_VTN = "...Tôi thường nghĩ về số phận của chúng ta."
L2_1.m_Talk_SCN = "……我时常会想，"
L2_1.m_Talk_DEU = "Ich denke oft über unser Schicksal nach."
L2_1.m_Talk_FRA = "... Je songe souvent à notre sort."
