L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@143#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 7
L6_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_VoiceFileName = "TUTORIAL_VOICE_2"
L6_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L6_1.m_Talk_KOREA = "만약 처음부터 이렇게 될 줄 알았다면……"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "もしこうなってしまうってわかっていたなら……"
L6_1.m_Talk_ENG = "Had we known things would happen like this..."
L6_1.m_Talk_TWN = "如果當初知道事情會變成這樣……"
L6_1.m_Talk_THA = "ถ้าเรารู้ว่าเรื่องราวจะออกมาเป็นแบบนี้..."
L6_1.m_Talk_VTN = "Nếu biết trước sẽ xảy ra như thế này..."
L6_1.m_Talk_SCN = "如果早知道会变成这样……"
L6_1.m_Talk_DEU = "Hätten wir gewusst, wie sich die Dinge entwickeln …"
L6_1.m_Talk_FRA = "Si nous avions su que les choses finiraient ainsi..."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@144#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 7
L7_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_VoiceFileName = "TUTORIAL_VOICE_3"
L7_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L7_1.m_Talk_KOREA = "우린 지금과는 달라졌을까?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "私たちは今と違っていたのかな？"
L7_1.m_Talk_ENG = "Would we have made different choices?"
L7_1.m_Talk_TWN = "我們的結局會不會和現在不同呢？"
L7_1.m_Talk_THA = "เราจะเลือกแบบอื่นไหม?"
L7_1.m_Talk_VTN = "Chúng ta có đưa ra những lựa chọn khác không?"
L7_1.m_Talk_SCN = "我们还会做出一样的选择吗？"
L7_1.m_Talk_DEU = "Hätten wir dann andere Entscheidungen getroffen?"
L7_1.m_Talk_FRA = "Aurions-nous pris d'autres décisions ?"
