L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@148#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 7
L11_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_VoiceFileName = "TUTORIAL_VOICE_4"
L11_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L11_1.m_Talk_KOREA = "의미없는 후회라는 건 알아."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "後悔しても意味ないってわかってる。"
L11_1.m_Talk_ENG = "I know my regret means nothing."
L11_1.m_Talk_TWN = "我知道後悔無濟於事。"
L11_1.m_Talk_THA = "ฉันรู้ดีว่าความเสียใจของฉันไม่มีความหมายอะไรเลย"
L11_1.m_Talk_VTN = "Tôi biết rằng tiếc nuối cũng chẳng ích gì."
L11_1.m_Talk_SCN = "我知道后悔无济于事。"
L11_1.m_Talk_DEU = "Ich weiß, dass mein Bedauern nichts ändert."
L11_1.m_Talk_FRA = "Je sais que mes regrets n'ont aucune valeur."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@149#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 7
L12_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_VoiceFileName = "TUTORIAL_VOICE_5"
L12_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "인간도, 신도 지나가 버린 운명을 되돌릴 수는 없으니까."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "人間も、神も過ぎ去った運命を巻き戻すことはできないから。"
L12_1.m_Talk_ENG = "No man or god can change the past."
L12_1.m_Talk_TWN = "無論是人類還是神仙，都無法讓時光倒流。"
L12_1.m_Talk_THA = "ไม่มีมนุษย์คนไหนหรือพระเจ้าองค์ใดเปลี่ยนแปลงอดีตได้"
L12_1.m_Talk_VTN = "Không một người nào, hay thậm chí không một vị thần nào có thể thay đổi quá khứ."
L12_1.m_Talk_SCN = "就算是奇迹般的存在，也无法让时光倒流。"
L12_1.m_Talk_DEU = "Weder Mensch noch Gott vermag die Vergangenheit zu ändern."
L12_1.m_Talk_FRA = "Nul homme ni dieu ne peut changer le passé."
L13_1 = {}
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 7
L13_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
