L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@151#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 7
L14_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_VoiceFileName = "TUTORIAL_VOICE_6"
L14_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L14_1.m_Talk_KOREA = "그러니까…… 너는 나처럼 바보 같은 선택을 하지 않길 바래."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "だから……あなたは私みたいな誤った選択はしないでほしいの。"
L14_1.m_Talk_ENG = "So, please do not make the same foolish mistake I made."
L14_1.m_Talk_TWN = "所以……我希望你別像我一樣做出愚蠢的選擇。"
L14_1.m_Talk_THA = "ดังนั้น โปรดอย่าได้ทำผิดพลาดโง่ๆ เหมือนที่ฉันเคยทำเลย"
L14_1.m_Talk_VTN = "Vậy nên, đừng phạm phải lỗi lầm ngu xuẩn như tôi."
L14_1.m_Talk_SCN = "所以……我希望你别像我一样做出愚蠢的选择。"
L14_1.m_Talk_DEU = "Deshalb: Machen Sie bitte nicht dieselben dummen Fehler wie ich."
L14_1.m_Talk_FRA = "Alors surtout, ne faites pas la même erreur que moi."
