L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@155#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 7
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_VoiceFileName = "TUTORIAL_VOICE_7"
L18_1.m_CharStrID = "SHE_NPC_NULL_NULL"
L18_1.m_Talk_KOREA = "가끔은, 포기하는 편이 더 나을 때도 있으니까."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "たまには、諦めた方がいい時もあるから。"
L18_1.m_Talk_ENG = "Sometimes it's better to give up rather than hold on."
L18_1.m_Talk_TWN = "有時候，放棄也許會更好一些。"
L18_1.m_Talk_THA = "บางทีการยอมปล่อยไปก็ดีกว่าเหนี่ยวรั้งไว้"
L18_1.m_Talk_VTN = "Đôi khi, buông bỏ tốt hơn là cố níu kéo."
L18_1.m_Talk_SCN = "有时候，放弃也许会更好一些。"
L18_1.m_Talk_DEU = "Manchmal ist es besser, aufzugeben, als an etwas festzuhalten."
L18_1.m_Talk_FRA = "Parfois, il vaut mieux baisser les bras que s'accrocher à tout prix."
