L22_1.m_Talk_THA = "ลาก่อนนะ"
L22_1.m_Talk_VTN = "Vậy, tạm biệt."
L22_1.m_Talk_SCN = "所以……再见了。"
L22_1.m_Talk_DEU = "Leben Sie wohl."
L22_1.m_Talk_FRA = "Adieu, donc."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@160#Talk"
