L23_1.m_Talk_KOREA = "이제 헤어질 시간이야."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "もうお別れの時間ね。"
L23_1.m_Talk_ENG = "It's time for us to part ways. "
L23_1.m_Talk_TWN = "離別時刻到了。"
L23_1.m_Talk_THA = "ถึงเวลาที่เราต้องแยกจากกันไปแล้ว"
L23_1.m_Talk_VTN = "Đã đến lúc chúng ta phải chia tay nhau rồi."
