L30_1.m_CutScenID = 7
L30_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L30_1.m_VoiceFileName = "TUTORIAL_VOICE_10"
L30_1.m_CharStrID = "QM_MARK_ANY_NOIMAGE"
L30_1.m_Talk_KOREA = "네, 부사장님. 지금 막 공항 라운지에 도착했습니다."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "はい、副社長。今ちょうど空港のラウンジに着きました。"
L30_1.m_Talk_ENG = "Yes, Madame Vice President. I just arrived at the airport lounge."
L30_1.m_Talk_TWN = "是，副總。我剛剛抵達了機場貴賓室。"
L30_1.m_Talk_THA = "ค่ะ คุณรองประธาน ฉันเพิ่งมาถึงเลาจ์สนามบินค่ะ"
L30_1.m_Talk_VTN = "Vâng, thưa Phó Chủ Tịch. Tôi vừa tới sảnh sân bay."
L30_1.m_Talk_SCN = "是，副总。刚刚抵达机场休息厅。"
L30_1.m_Talk_DEU = "Ja, Frau Vizevorsitzende. Ich bin gerade in der Flughafenlounge eingetroffen."
L30_1.m_Talk_FRA = "Oui, madame la vice-présidente. Je viens d'arriver à la salle d'attente de l'aéroport."
