L33_1 = {}
L33_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@170#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 7
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_VoiceFileName = "TUTORIAL_VOICE_11"
L33_1.m_CharStrID = "QM_MARK_ANY_NOIMAGE"
L33_1.m_Talk_KOREA = "네. 주무시고 계시네요. 비행기를 오래 타서 피곤하신가 봐요."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "はい、眠っていますね。長時間のフライトでお疲れのようです。"
L33_1.m_Talk_ENG = "Yes, he's sleeping. Must be exhausted from his long plane trip."
L33_1.m_Talk_TWN = "是，他正在閉目養神，應該是因為長時間飛行的關係，所以有點疲憊。"
L33_1.m_Talk_THA = "ค่ะ เขาหลับอยู่ คงเหนื่อยจากการนั่งเครื่องบินนานๆ"
L33_1.m_Talk_VTN = "Ừ, anh ấy đang ngủ. Có lẽ anh ấy rất mệt sau chuyến bay dài."
L33_1.m_Talk_SCN = "嗯，我看到了，但他好像正在休憩。可能是因为长时间坐飞机累了。"
L33_1.m_Talk_DEU = "Ja, er schläft. Sicher ist er nach dem langen Flug erschöpft."
L33_1.m_Talk_FRA = "Oui, il dort. Ce long vol a dû l'épuiser."
