L37_1 = {}
L37_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@174#Talk"
L37_1.m_CutScenProcessKey = 37
L37_1.m_CutScenID = 7
L37_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_VoiceFileName = "TUTORIAL_VOICE_12"
L37_1.m_CharStrID = "QM_MARK_ANY_NOIMAGE"
L37_1.m_Talk_KOREA = "아, 잠시만요. 지금 깨어나신 것 같아요."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "あ、お待ちください。今お目覚めになったみたいです。"
L37_1.m_Talk_ENG = "Oh, wait. He just woke up."
L37_1.m_Talk_TWN = "咦，請等一下，他好像醒了。"
L37_1.m_Talk_THA = "อ๊ะ เดี๋ยวนะคะ เขาตื่นแล้วค่ะ"
L37_1.m_Talk_VTN = "Ồ, chờ đã. Anh ta vừa tỉnh lại."
L37_1.m_Talk_SCN = "咦，请等一下，他好像醒了。"
L37_1.m_Talk_DEU = "Oh, Moment. Er ist gerade aufgewacht"
L37_1.m_Talk_FRA = "Oh, attendez. Il vient de se réveiller."
L38_1 = {}
L38_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@175#Talk"
L38_1.m_CutScenProcessKey = 38
L38_1.m_CutScenID = 7
L38_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_VoiceFileName = "TUTORIAL_VOICE_13"
L38_1.m_CharStrID = "QM_MARK_ANY_NOIMAGE"
L38_1.m_Talk_KOREA = "다시 연락드리겠습니다, 부사장님."
L38_1.m_fTalkTime = 0.03
L38_1.m_Talk_JPN = "それではまた連絡します。失礼します。"
L38_1.m_Talk_ENG = "I'll call you right back."
L38_1.m_Talk_TWN = "我等會再聯繫副總。"
L38_1.m_Talk_THA = "เดี๋ยวฉันโทรกลับนะคะ"
L38_1.m_Talk_VTN = "Tôi sẽ gọi lại cho cô ngay."
L38_1.m_Talk_SCN = "我等会儿再联系您。"
L38_1.m_Talk_DEU = "Ich rufe dich gleich zurück."
L38_1.m_Talk_FRA = "Je vous rappelle très vite."
