L42_1 = {}
L42_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE1_START@179#Talk"
L42_1.m_CutScenProcessKey = 42
L42_1.m_CutScenID = 7
L42_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_VoiceFileName = "TUTORIAL_VOICE_14"
L42_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L42_1.m_Talk_KOREA = "안녕하세요. 코핀 컴퍼니의 김하나 관리부장이라고 합니다."
L42_1.m_fTalkTime = 0.03
L42_1.m_Talk_JPN = "初めまして。コフィンカンパニーの管理部長、ナカシマ・スズカと申します。"
L43_1 = "Hello. I'm Kim Hana, a manager at the Coffin Company."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我是科芬公司的管理部長金荷娜。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "สวัสดี ฉันชื่อคิม ฮานาค่ะ เป็นผู้จัดการบริษัทคอฟฟิน"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi là Kim Hana, quản lý tại Công Ty Coffin."
L42_1.m_Talk_VTN = L43_1
L43_1 = "您好，我是科芬公司的管理部部长千夜。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hallo. Ich bin Kim Hana, Managerin bei der Coffin Company."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Bonjour. Je m'appelle Kim Hana, directrice de la Compagnie Coffin."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP1_ACT1_STAGE1_START@180#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 7
L43_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "TUTORIAL_VOICE_15"
L43_1.m_VoiceFileName = L44_1
L43_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L44_1 = "죄송합니다. 주무시고 계시는데 통화 소리가 너무 컸죠?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "申し訳ありません。お休みのところ、通話の音が少し大きかったでしょうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Was my voice too loud? I'm sorry."
L43_1.m_Talk_ENG = L44_1
L44_1 = "抱歉，我說話太大聲，打擾到您休息了吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันเสียงดังไปรึเปล่าคะ? ขอโทษทีนะคะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi nói quá lớn sao? Xin lỗi nhé."
L43_1.m_Talk_VTN = L44_1
L44_1 = "抱歉，我说话声音太大，打扰您休息了吧？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "War meine Stimme zu laut? Tut mir leid."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je parle trop fort ? Pardonnez-moi."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP1_ACT1_STAGE1_START@181#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 7
L44_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "TUTORIAL_VOICE_16"
L44_1.m_VoiceFileName = L45_1
L44_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L45_1 = "실은 오늘 저희 회사에 취임하실 새로운 사장님을 모시고 오라는 지시를 받았습니다만,"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "実は、本日我が社に就任する新社長を迎えに行ってほしいという指示を受けました。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I was told to escort our new president."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我收到指示來接我們公司新上任的老闆。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันได้รับคำสั่งให้มาดูแลประธานคนใหม่ของเราค่ะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi được lệnh hộ tống chủ tịch mới."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我收到指示来接我们公司新上任的老板。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Mir wurde gesagt, ich soll unseren neuen Vorsitzenden eskortieren."
L44_1.m_Talk_DEU = L45_1
L45_1 = "On m'a priée d'escorter notre nouveau président."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP1_ACT1_STAGE1_START@182#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 7
L45_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "TUTORIAL_VOICE_17"
L45_1.m_VoiceFileName = L46_1
L45_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L46_1 = "인상착의를 봐선 제가 찾던 분이 맞는 것 같은데……?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "顔つきや服装からして、どうやら私が探していた方で間違いないようですが……？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I believe you are the one I am looking for, correct?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "從衣著相貌來看，說的應該就是您……吧？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "คุณคือคนที่ฉันตามหาอยู่ใช่มั้ยคะ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi tin rằng anh là người mà tôi cần tìm, đúng không?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "从衣着相貌来看，应该就是您……没错吧？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Das dürften dann wohl Sie sein, richtig?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je pense que c'est vous que je cherche, n'est-ce pas ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
