L50_1 = "EP1_ACT1_STAGE1_START@186#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 7
L49_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_bGameObjectBGType = true
L50_1 = "BASE_LAUGH"
L49_1.m_GameObjectBGAniName = L50_1
L49_1.m_bGameObjectBGLoop = true
L50_1 = "TUTORIAL_VOICE_19"
L49_1.m_VoiceFileName = L50_1
L49_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L50_1 = "역시 그러셨네요. 늦지 않게 와서 다행이에요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "やはりそうだったんですね。間に合って良かったです。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Good. I'm glad I didn't miss you."
L49_1.m_Talk_ENG = L50_1
L50_1 = "果然沒錯！幸好有接到人。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ดีจังค่ะ ฉันดีใจที่ไม่พลาดไปกับคุณนะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tốt. Tôi rất vui là tôi đã không bỏ lỡ việc gặp ngài."
L49_1.m_Talk_VTN = L50_1
L50_1 = "果然是呢，幸好没来晚。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Gut. Ich bin froh, dass wir uns nicht verpasst haben."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Parfait. Je suis contente de ne pas vous avoir raté."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP1_ACT1_STAGE1_START@187#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 7
L50_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "TUTORIAL_VOICE_20"
L50_1.m_VoiceFileName = L51_1
L50_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L51_1 = "갑자기 회사를 인수하셔서 어떤 분일까 궁금했는데, 부사장님 말씀보다 더 젊고 훤칠하시네요. "
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "急に我が社を買収されたと聞いて、一体どんな方なんだろうと気になっていたんですが……副社長から聞いていたよりも、はるかに若くてカッコいい方ですね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I wondered who acquired the company so all of a sudden. You look much younger and handsomer than the Vice President said. "
L50_1.m_Talk_ENG = L51_1
L51_1 = "我一直很好奇要來接手公司的人到底是何方神聖，您看起來比副總說的還年輕體面呢！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันสงสัยอยู่เลยว่าใครซื้อบริษัทเราแบบปุบปับ คุณดูเด็กและหล่อกว่าที่รองประธานบอกไว้มากเลยค่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi vẫn luôn tò mò về người đã mua công ty một cách đột ngột như thế. Ngài trông trẻ hơn và đẹp trai hơn so với những gì Phó Chủ Tịch nói đấy."
L50_1.m_Talk_VTN = L51_1
L51_1 = "听说您收购了我们公司，我一直很好奇……您比副总说的更年轻，更帅气。 "
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich habe mich schon gefragt, wer die Firma so plötzlich erworben hat. Sie sehen viel jünger und attraktiver aus, als die Vizevorsitzende gesagt hat."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Je me demandais qui pouvait avoir acheté l'entreprise aussi soudainement. Je ne m'attendais pas à un aussi beau jeune homme."
L50_1.m_Talk_FRA = L51_1
