L2_1 = "EP1_ACT1_STAGE1_START@188#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 7
L1_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_bGameObjectBGType = true
L2_1 = "BASE_SURPRISE"
L1_1.m_GameObjectBGAniName = L2_1
L1_1.m_bGameObjectBGLoop = true
L2_1 = "TUTORIAL_VOICE_21"
L1_1.m_VoiceFileName = L2_1
L1_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L2_1 = "……아, 아니, 조금 이상하게 들릴 수 있겠지만 불순한 이유로 한 말은 아니고요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "……いや、あの……変に聞こえるかもしれませんが、別に不純な目的があって褒めたわけではありませんから……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "O-oh, I didn't mean to be flirty..."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我、我誇您沒有別的意思……"
L1_1.m_Talk_TWN = L2_1
L2_1 = "อะ-อุ๊ย ฉันไม่ได้จะจีบนะคะ..."
L1_1.m_Talk_THA = L2_1
L2_1 = "Ồ, tôi không có ý cưa cẩm gì đâu..."
L1_1.m_Talk_VTN = L2_1
L2_1 = "我，我夸您没有别的意思……"
L1_1.m_Talk_SCN = L2_1
L2_1 = "O-oh, das sollte jetzt kein Flirt sein …"
L1_1.m_Talk_DEU = L2_1
L2_1 = "O-oh, je ne voulais pas vous faire des avances..."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP1_ACT1_STAGE1_START@189#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 7
L2_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_bGameObjectBGType = true
L3_1 = "BASE_DESPAIR"
L2_1.m_GameObjectBGAniName = L3_1
L2_1.m_bGameObjectBGLoop = true
L3_1 = "TUTORIAL_VOICE_22"
L2_1.m_VoiceFileName = L3_1
L2_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L3_1 = "어디까지나 새로 모시게 된 사장님과 잘 지냈으면 좋겠다는 그런…… 공적인 이유 때문에……"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あくまで新しい社長とこれからうまくやっていきたいっていうか……そういう理由なのであって……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I was just trying to be polite, since you'll be my new boss..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我只是希望盡快和您熟絡起來……絕對沒有私心的……。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฉันพยายามจะสุภาพน่ะค่ะ เพราะคุณจะเป็นบอสคนใหม่ของเรา..."
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi chỉ muốn nói chuyện lịch sự thôi, vì ngài sẽ là ông chủ mới..."
L2_1.m_Talk_VTN = L3_1
L3_1 = "您是老板，就当是我恭维您好了……可不是出于私心……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich wollte nur höflich sein. Schließlich sind Sie mein neuer Boss …"
L2_1.m_Talk_DEU = L3_1
L3_1 = "J'essayais juste d'être polie, puisque vous êtes mon nouveau patron..."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP1_ACT1_STAGE1_START@190#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 7
L3_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "TUTORIAL_VOICE_23"
L3_1.m_VoiceFileName = L4_1
L3_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L4_1 = "절대 지난 주 맞선에서도 퇴짜 맞았다고 급해진 건 아니에요!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "別に先週のお見合いに失敗したのは関係ありませんから！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Not because my date went wrong last week!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "絕對不是因為我上週相親失敗就想要亂槍打鳥喔！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ไม่ใช่เพราะเดตฉันอาทิตย์ที่แล้วเละไม่เป็นท่าหรอกนะคะ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Không phải vì cuộc hẹn hò tuần trước của tôi vỡ lở đâu!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "绝对不是因为我上周相亲失败！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Das hat rein gar nichts damit zu tun, dass mein Date letzte Woche in die Hose gegangen ist!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Et pas parce que mon rendez-vous de la semaine dernière s'est mal passé !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
