L6_1 = "BASE_LAUGH"
L5_1.m_GameObjectBGAniName = L6_1
L5_1.m_bGameObjectBGLoop = true
L6_1 = "TUTORIAL_VOICE_25"
L5_1.m_VoiceFileName = L6_1
L5_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L6_1 = "여, 여기 라운지는 조금 덥네요! 사장님께선 괜찮으세요?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "こ、ここのラウンジはちょっと暑いですね！社長は大丈夫ですか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "What am I even saying? Gosh, it's getting hot in here."
L5_1.m_Talk_ENG = L6_1
L6_1 = "貴賓室好熱喔！老闆您不熱嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "พูดอะไรของฉันเนี่ย? โอย ในนี้ร้อนจังนะคะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi đang nói cái quái gì thế? Trời ạ, trong này nóng quá."
L5_1.m_Talk_VTN = L6_1
L6_1 = "……我这是在说什么呀？啊，这里好热。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Was rede ich da überhaupt? Mann, ist das heiß hier drin!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Rah, qu'est-ce que je raconte ? Ce qu'il fait chaud ici."
L5_1.m_Talk_FRA = L6_1
