L7_1[L8_1] = L9_1
L8_1 = "당황하지 않아도 괜찮아."
L7_1.m_Talk_KOREA = L8_1
L8_1 = "そんなに慌てなくても大丈夫だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You don't have to be so nervous around me."
L7_1.m_Talk_ENG = L8_1
L8_1 = "沒關係，妳不用緊張。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "อยู่กับผมไม่ต้องประหม่าขนาดนั้นก็ได้"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô không phải lo lắng thế khi ở cạnh tôi."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你不用紧张。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Kein Grund, nervös zu sein."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ne soyez pas si nerveuse en ma présence."
L7_1.m_Talk_FRA = L8_1
