L12_1 = "TUTORIAL_VOICE_28"
L11_1.m_VoiceFileName = L12_1
L11_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L12_1 = "아, 어… 어쨌든 바로 회사로 모시겠습니다! 사장님!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "え、あ……とりあえず会社まで案内しますね、社長！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Ah, err... Anyway, let me take you to the office right away, Boss!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "我…我們現在就出發去公司吧！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อ๊ะ เอ่อ... เอาละ ฉันพาคุณไปที่ห้องทำงานเลยดีกว่าค่ะ บอส!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ah, err... Dù sao thì hãy để tôi đưa ngài đến văn phòng ngay nhé, Ông Chủ!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "啊，那……那什么，我马上带您去公司！老板！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ah, äh … Dann will ich Sie gleich mal ins Büro bringen, Boss!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ah, euh... Bref, je vous emmène de ce pas au bureau, monsieur !"
L11_1.m_Talk_FRA = L12_1
