L18_1 = "TUTORIAL_VOICE_29"
L17_1.m_VoiceFileName = L18_1
L17_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L18_1 = "슬슬 해가 질 시간이네요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "そろそろ日が暮れる時間ですね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The sun is about to set."
L17_1.m_Talk_ENG = L18_1
L18_1 = "太陽下山了呢！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ดวงอาทิตย์ใกล้ตกแล้ว"
L17_1.m_Talk_THA = L18_1
L18_1 = "Mặt trời sắp lặn rồi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "太阳快落山了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Die Sonne geht gleich unter."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Le soleil va bientôt se coucher."
L17_1.m_Talk_FRA = L18_1
