L19_1 = "EP1_ACT1_STAGE1_START@205#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 7
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "TUTORIAL_VOICE_30"
L18_1.m_VoiceFileName = L19_1
L18_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L19_1 = "아, 혹시 그라운드 원은 처음이세요? 경치가 좀 특이하죠?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "もしかして、グラウンド・ワンは初めてですか？変わった景色ですよね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Oh, is this your first time in this city, Ground One? It looks peculiar, doesn't it?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "您是第一次來G1嗎？風景很特別吧！？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อ๊ะ นี่เป็นครั้งแรกที่คุณมาที่เมืองกราวด์วันแห่งนี้เหรอคะ? มันดูแปลกใช่มั้ย?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ồ, đây là lần đầu tiên ngài tới thành phố này, Ground One, ư? Trông nó kỳ lạ nhỉ?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "啊，您是第一次来G1吗？这里的风景很特别吧？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Sind Sie zum ersten Mal in Ground One? Sieht merkwürdig aus, nicht wahr?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Oh, c'est la première fois que vous venez dans cette ville, le Site n°1 ? C'est spécial, n'est-ce pas ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP1_ACT1_STAGE1_START@206#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 7
L19_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "TUTORIAL_VOICE_31"
L19_1.m_VoiceFileName = L20_1
L19_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L20_1 = "저기 보이는 빛이 관리실패 때 생긴 대균열인데, 아직 닫히지 않아서 침식재난이 자주 발생하는 편이에요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "あちらに見える光が、管理失敗の時にできた大亀裂なんですが、まだ塞がってないので、侵食災害がよく起こるんです。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "The light you see over there is leaking through the Grand Dimension Crevice, created during the Administration Failure. It's still open and often causing Corruption disasters."
L19_1.m_Talk_ENG = L20_1
L20_1 = "您有看到那道光嗎？那就是管理失敗時產生的大峽谷，現在還沒關閉，所以經常發生侵蝕災難。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แสงที่คุณเห็นตรงนั้นออกมาจากรอยแยกมิติขนาดมหึมา ซึ่งเกิดขึ้นระหว่างการล่มสลายขององค์การบริหารโลก มันยังเปิดอยู่และมักก่อให้เกิดภัยพิบัติคอร์รัปชั่น"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ánh sáng mà ngài nhìn thấy ở đằng kia bị rò rỉ từ Khe Nứt Không Gian Vĩ Đại. Nó xuất hiện sau sự kiện Cục Quản Lý Sụp Đổ. Nó vẫn còn mở và thường gây ra các thảm họa ăn mòn."
L19_1.m_Talk_VTN = L20_1
L20_1 = "那边那束光是管理失败时产生的大裂谷，直到现在都还没闭合，所以经常会发生侵蚀灾难。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Das Licht da drüben kommt geradewegs aus der Großen Dimensionskluft, die während des Scheiterns der Administration entstanden ist. Sie ist immer noch offen und verursacht Verderbniskatastrophen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "La lumière que vous voyez là filtre à travers la crevasse de grande dimension, créée lors de la Chute de l'Administration. Elle est toujours ouverte et cause souvent des sinistres de corruption."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP1_ACT1_STAGE1_START@207#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 7
L20_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "TUTORIAL_VOICE_32"
L20_1.m_VoiceFileName = L21_1
L20_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L21_1 = "그래도 안심하세요. 그만큼 침식재난에 대응할 태스크포스 컴퍼니들도 많이 모여 있으니까요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "でも、安心してくださいね。その分、侵食災害に対応できるタスクフォースカンパニーもたくさん集まっていますから。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "But don't worry. There are many TASKFORCE companies in the city that are ready to respond to such disasters at a minute's notice."
L20_1.m_Talk_ENG = L21_1
L21_1 = "不過您放心吧！就算發生侵蝕災難，這邊也有許多特遣勢力公司可以處理的！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แต่ไม่ต้องห่วงนะคะ ในเมืองมีบริษัททาสก์ฟอร์สหลายแห่งที่พร้อมรับมือกับหายนะทันที"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nhưng đừng lo. Có rất nhiều công ty TASKFORCE trong thành phố sẵn sàng ứng phó với những thảm họa ấy ngay khi có thông báo."
L20_1.m_Talk_VTN = L21_1
L21_1 = "不过您放心。这里聚集了很多应对侵蚀灾难的特遣势力公司。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Aber machen Sie sich keine Sorgen. Es gibt viele TASKFORCE-Unternehmen in der Stadt, die binnen kürzester Zeit auf diese Katastrophen reagieren."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Mais n'ayez crainte. Il y a en ville de nombreuses entreprises TASKFORCE prêtes à réagir immédiatement en cas de catastrophe."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
