L21_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L22_1 = "저희 코핀 컴퍼니도 그 중 하나고요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "私たちのコフィンカンパニーも同じです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "The Coffin Company is one of them."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我們科芬公司也是其中之一喔！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "บริษัทคอฟฟินก็เป็นหนึ่งในนั้น"
L21_1.m_Talk_THA = L22_1
L22_1 = "Công Ty Coffin là một trong số đó."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我们科芬公司也是其中之一。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Die Coffin Company ist eines davon."
L21_1.m_Talk_DEU = L22_1
L22_1 = "La Compagnie Coffin en fait partie."
