L24_1 = "그런데 왜 버스를 타고 가나?"
L23_1.m_Talk_KOREA = L24_1
L24_1 = "それより、なぜバス移動なのか聞いてもいいかな？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "So... Why are we taking a bus?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "不過為什麼是搭公車？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แล้ว... ทำไมเราต้องขึ้นรถเมล์ด้วยล่ะ?"
L23_1.m_Talk_THA = L24_1
