L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 7
L27_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
