L28_1 = "TUTORIAL_VOICE_36"
L27_1.m_VoiceFileName = L28_1
L27_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L28_1 = "사장님께서도 잘 아시겠지만, 최근 여러 문제로 회사 재정 상태가 많이 어려웠거든요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "社長もご存知かと思いますが、ここ最近、様々な問題によって会社の財政状況がとても厳しい状態です。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "As you may already know, the company has suffered several setbacks that led to its financial crisis."
L27_1.m_Talk_ENG = L28_1
L28_1 = "您也知道，公司最近發生很多事，所以財務不是很寬裕。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อย่างที่คุณอาจรู้แล้วนะคะ บริษัทล้มเหลวมาหลายครั้งจนกลายนำมาสู่วิกฤติทางการเงินในตอนนี้น่ะค่ะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Như ngài có thể đã biết rồi, công ty đã chịu vài tổn thất khiến cho chúng ta lâm vào khủng hoảng tài chính như hiện tại."
L27_1.m_Talk_VTN = L28_1
L28_1 = "老板您应该也知道，最近因为诸多问题，公司的财政情况不怎么好。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wie Sie vielleicht schon wissen, hatte das Unternehmen diverse Rückschläge und steckt finanziell in der Klemme."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Comme vous le savez peut-être, l'entreprise a subi plusieurs revers qui nous ont conduits à une crise financière."
L27_1.m_Talk_FRA = L28_1
