L31_1 = "TUTORIAL_VOICE_37"
L30_1.m_VoiceFileName = L31_1
L30_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L31_1 = "저희 태스크포스는 침식체를 쓰러뜨려서 얻은 이터니움으로 수익을 올려야 하잖아요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "タスクフォースカンパニーが侵食体を倒して得たエタニウムで収益を上げるのはご存知ですね？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Usually, TASKFORCE companies make profit with Eternium from Corrupted Objects."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我們特遣勢力是靠消滅侵蝕體獲得的永恆之金來增加收入的不是嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ปกติแล้วบริษัททาสก์ฟอร์สจะทำกำไรจากอีเทอร์เนียมที่ได้จากวัตถุคอร์รัปต์"
L30_1.m_Talk_THA = L31_1
L31_1 = "Thông thường, các công ty TASKFORCE kiếm lời từ Vàng Vĩnh Cửu mà họ thu được trong các Vật Thể Ăn Mòn."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我们特遣势力是通过击杀侵蚀体后得到的能晶提高收益的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "In der Regel machen TASKFORCE-Unternehmen Gewinn mit Eternium aus Counterside-Objekten."
L30_1.m_Talk_DEU = L31_1
L31_1 = "D'ordinaire, les entreprises TASKFORCE s'enrichissent grâce à l'éternium des objets corrompus."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP1_ACT1_STAGE1_START@218#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 7
L31_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "TUTORIAL_VOICE_38"
L31_1.m_VoiceFileName = L32_1
L31_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L32_1 = "작전에 필요한 인력과 장비에 유지비가 많이 드는데, 사정이 있어서 제대로 된 작전은 못 한 지 한참 됐거든요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "作戦に必要な人材管理や、装備の維持には多額のコストがかかりますが、諸事情によりちゃんとした作戦はしばらくできていない状況なんです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "And hunting Corrupted Objects requires the manpower and gear that our company hasn't been able to afford for a while."
L31_1.m_Talk_ENG = L32_1
L32_1 = "作戰需要的人力和裝備維修的費用很龐大，因為一些原因已經許久沒能好好作戰了！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "และการล่าวัตถุคอร์รัปต์ก็ต้องใช้กำลังคนและอุปกรณ์ที่บริษัทของเราไม่มีเงินซื้อมาสักพักแล้ว"
L31_1.m_Talk_THA = L32_1
L32_1 = "Và săn Vật Thể Ăn Mòn phải có nhân lực và vật lực, những thứ mà công ty chúng ta vẫn chưa đủ khả năng để trang trải."
L31_1.m_Talk_VTN = L32_1
L32_1 = "作战时投入的人员和装备都需要大量费用来维持，因为财政情况不好，已经很久没有进行像样的作战了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Aber Counterside-Objekte zu jagen, erfordert Personal und Ausrüstung, die sich unsere Firma schon eine Weile nicht mehr leisten kann."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Or la traque d'objets corrompus nécessite une main-d'œuvre et de l'équipement que nous n'avons pas pu nous offrir depuis un certain moment."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP1_ACT1_STAGE1_START@219#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 7
L32_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "TUTORIAL_VOICE_39"
L32_1.m_VoiceFileName = L33_1
L32_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L33_1 = "사장님께서 인수해 주시지 않았다면 저희도 지금쯤 파산 절차를 밟고 있었겠죠."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "社長がいらっしゃらなかったら、\n我々は今頃破産手続きを進めていた頃でしょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "If you didn't take over, it would have been filing for bankruptcy by now."
L32_1.m_Talk_ENG = L33_1
L33_1 = "要不是老闆接手，我們現在應該正在申請破產吧！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "หากคุณไม่ได้เข้ามาซื้อกิจการ ที่นี่คงยื่นล้มละลายไปแล้ว"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nếu ngài không tiếp quản, có lẽ giờ tôi đã nộp đơn xin phá sản rồi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "如果老板您没收购我们公司，公司也许早就进入破产程序了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ohne Sie hätten wir inzwischen Insolvenz angemeldet."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Si vous ne nous aviez pas rachetés, nous aurions déjà déclaré faillite."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE1_START@220#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 7
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "TUTORIAL_VOICE_40"
L33_1.m_VoiceFileName = L34_1
L33_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L34_1 = "도산 위기는 넘겼다지만, VIP를 모시는데 택시 부르기도 어려울 지경이니까요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "倒産の危機は免れたものの、VIPのお迎えにタクシーを呼ぶ余裕すらなくて……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "For now, it still stands, but it can barely afford anything, even a taxi for its very own owner."
L33_1.m_Talk_ENG = L34_1
L34_1 = "雖然度過了破產的危機，但公司財務還是無法支付計程車的費用。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ตอนนี้บริษัทยังอยู่ แต่ก็แทบซื้ออะไรไม่ได้เลย ไม่มีแม้แต่ค่าแท็กซี่ให้เจ้าของคนใหม่"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hiện tại, công ty vẫn trụ được, nhưng khó mà đủ sức chi trả thêm cái gì, ngay cả tiền taxi cho chủ nhân của nó cũng vậy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "虽然躲过了破产危机，但现在连接待VIP的专车费都付不起了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Stand der Dinge ist, dass es die Firma noch gibt, sie sich aber nicht mal das Taxi für den neuen Eigentümer leisten kann."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Pour l'heure, l'entreprise tient le choc, mais elle n'a même pas le budget pour payer un taxi à son propriétaire."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE1_START@221#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 7
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "TUTORIAL_VOICE_41"
L34_1.m_VoiceFileName = L35_1
L34_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L35_1 = "아무튼 그런 이유로, 현재 활동 중인 현장 대원은 한 명뿐입니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "そんなわけで、現在活動中の現場隊員は一人のみです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "For that same reason, we have only one active field agent at this moment."
L34_1.m_Talk_ENG = L35_1
L35_1 = "因為這樣，現在活動中的現場隊員只有一位。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "และด้วยเหตุผลเดียวกัน ตอนนี้เราก็เลยมีเจ้าหน้าที่ภาคสนามทำงานอยู่แค่คนเดียวค่ะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cũng vì thế, hiện giờ chúng tôi chỉ có một đặc vụ chiến trường hoạt động thôi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "并且，目前能执行任务的现场队员只有一位。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Aus diesem Grund haben wir aktuell auch nur einen einzigen aktiven Agenten im Außeneinsatz."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Pour cette même raison, nous ne disposons actuellement que d'un seul agent actif sur le terrain."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP1_ACT1_STAGE1_START@222#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 7
L35_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "TUTORIAL_VOICE_42"
L35_1.m_VoiceFileName = L36_1
L35_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L36_1 = "그래도 너무 걱정 마세요. 무급 휴직 중이던 소대장님이 이번에 복직하셨거든요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "でも、あまり心配しないでください。休職中だった小隊長が今回復職したんです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Don't worry, though. A squad commander who was on unpaid leave just has returned."
L35_1.m_Talk_ENG = L36_1
L36_1 = "不過您放心！之前留職停薪的小隊長這次復職囉！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่ไม่ต้องห่วงนะคะ ผู้บัญชาการหน่วยที่เคยลางานแบบไม่รับเงินเดือนเพิ่งกลับมา"
L35_1.m_Talk_THA = L36_1
L36_1 = "Dù vậy, đừng lo. Tổng tư lệnh tiểu đội đang nghỉ phép không lương vừa quay trở lại."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不过您不用太担心。因为停薪留职的小队队长这次复职了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber machen Sie sich keine Sorgen. Eine Truppenkommandantin, die in unbezahltem Urlaub war, ist gerade zurückgekehrt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais ne vous en faites pas. Un commandant d'escouade précédemment en congé sans solde vient de faire son retour."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT1_STAGE1_START@223#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 7
L36_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "TUTORIAL_VOICE_43"
L36_1.m_VoiceFileName = L37_1
L36_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L37_1 = "거기에 사장님께서 투자해 주신 자금으로 신입 사원 한 분도 충원했답니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "それに社長からの投資金で新入社員も一人増員しました。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Furthermore, we hired a new employee with the money you invested."
L36_1.m_Talk_ENG = L37_1
L37_1 = "聽說還用老闆投資的資金增加了一名新職員呢！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แล้วก็ เราเอาเงินลงทุนของคุณไปจ้างพนักงานใหม่มาคนนึงแล้วด้วย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ngoài ra, chúng tôi còn thuê được một nhân viên mới với số tiền mà ngài đã đầu tư."
L36_1.m_Talk_VTN = L37_1
L37_1 = "而且我们还用老板您投资的钱雇了一位新职员。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Außerdem haben wir mit Ihrem Geld eine neue Mitarbeiterin eingestellt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "De plus, nous avons engagé une nouvelle employée avec l'argent que vous avez investi."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP1_ACT1_STAGE1_START@224#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 7
L37_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "TUTORIAL_VOICE_44"
L37_1.m_VoiceFileName = L38_1
L37_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L38_1 = "경력은 짧지만 다른 분들이 베테랑이니까, 빠르게 적응하실 거라고 생각해요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "経歴は浅いですが、他の隊員たちがベテランなので、早く慣れてくれると思います。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "She's fairly new to this industry, but everyone else is a veteran. I'm sure they can help her acclimate quickly."
L37_1.m_Talk_ENG = L38_1
L38_1 = "雖然新人資歷不深，但其他人都是老手，相信新人應該很快就能適應的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เธอยังค่อนข้างใหม่กับอุตสาหกรรมนี้ แต่คนอื่นๆ มีประสบการณ์มามาก ฉันมั่นใจว่าพวกเขาจะช่วยให้เธอปรับตัวได้อย่างรวดเร็วค่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cô ấy khá mới mẻ với ngành này, nhưng những người còn lại đều kỳ cựu cả. Tôi chắc là họ có thể giúp cô ấy làm quen nhanh thôi."
L37_1.m_Talk_VTN = L38_1
L38_1 = "虽然经验不足，但其他人都是老兵，相信很快就会适应的。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sie ist noch ziemlich neu in der Branche, aber alle anderen sind ja Veteranen. Sie helfen ihr sicher, sich schnell einzuleben."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Elle débute dans le métier, mais tous les autres sont des vétérans. À leurs côtés, je ne doute pas qu'elle s'adaptera rapidement."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
