L41_1 = "EP1_ACT1_STAGE1_START@227#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L40_1.m_CutScenProcessKey = 90
L40_1.m_CutScenID = 7
L40_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
