L41_1 = "TUTORIAL_VOICE_45"
L40_1.m_VoiceFileName = L41_1
L40_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L41_1 = "어라? 도로가 조금 막히네요? 무슨 일이지?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あれ、渋滞のようですね。どうしたんだろう？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Hmm? There's unusually heavy traffic. I wonder why."
L40_1.m_Talk_ENG = L41_1
L41_1 = "嗯？好像有點塞車？是發生什麼事?"
L40_1.m_Talk_TWN = L41_1
L41_1 = "หืมม? ทำไมรถติดผิดปกติ อยากรู้จังว่าเกิดอะไรขึ้น"
L40_1.m_Talk_THA = L41_1
L41_1 = "Hmm? Tắc đường bất ngờ nhỉ. Tôi không hiểu tại sao."
L40_1.m_Talk_VTN = L41_1
L41_1 = "咦？怎么堵了？发生什么事了吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Hmm? Es ist ungewöhnlich viel Verkehr. Ich frage mich, warum."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Tiens ? Il y a plus de trafic que d'ordinaire. Je me demande bien pourquoi."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 7
