L45_1 = "m_EndFXSoundName"
L46_1 = "FX_CUTSCEN_CROWD_NOISE_02"
L44_1[L45_1] = L46_1
L45_1 = "TUTORIAL_VOICE_46"
L44_1.m_VoiceFileName = L45_1
L45_1 = "<color=#ffd34c>그라운드 원, 도시관리국에서 알려드립니다.</color>"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "<color=#ffd34c>グラウンド・ワン、都市管理局からお知らせします。</color>"
L44_1.m_Talk_JPN = L45_1
L45_1 = "<color=#ffd34c>This is an announcement from Ground One, City Managements.</color>"
L44_1.m_Talk_ENG = L45_1
L45_1 = "<color=#ffd34c>G1、城市管理局通知。</color>"
L44_1.m_Talk_TWN = L45_1
L45_1 = "<color=#ffd34c>นี่คือประกาศจากสำนักบริหารเมือง กราวด์วัน</color>"
L44_1.m_Talk_THA = L45_1
L45_1 = "<color=#ffd34c>Đây là thông báo từ Ban Quản Lý Thành Phố, Ground One.</color>"
L44_1.m_Talk_VTN = L45_1
L45_1 = "<color=#ffd34c>G1城市管理局播报通知。</color>"
L44_1.m_Talk_SCN = L45_1
L45_1 = "<color=#ffd34c>Dies ist eine Mitteilung der Stadtverwaltung von Ground One.</color>"
L44_1.m_Talk_DEU = L45_1
L45_1 = "<color=#ffd34c>Ceci est une annonce de la direction des cités du Site n°1.</color>"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP1_ACT1_STAGE1_START@232#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 7
L45_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "TUTORIAL_VOICE_47"
L45_1.m_VoiceFileName = L46_1
L46_1 = "<color=#ffd34c>현재, 도심 전역에 침식파 밀도가 서서히 증가하고 있습니다.</color>"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>現在、都心全域で侵食波濃度が徐々に上昇しています。</color>"
L45_1.m_Talk_JPN = L46_1
L46_1 = "<color=#ffd34c>The density of Corruption rays is gradually increasing across the city center.</color>"
L45_1.m_Talk_ENG = L46_1
L46_1 = "<color=#ffd34c>現在市中心全區的侵蝕波密度持續增加中。</color>"
L45_1.m_Talk_TWN = L46_1
L46_1 = "<color=#ffd34c>ขณะนี้รังสีคอร์รัปชั่นเริ่มทวีความหนาแน่นขึ้นทีละน้อยทั่วพื้นที่ใจกลางเมือง</color>"
L45_1.m_Talk_THA = L46_1
L46_1 = "<color=#ffd34c>Mật độ của Tia Ăn Mòn đang tăng dần ở trung tâm thành phố.</color>"
L45_1.m_Talk_VTN = L46_1
L46_1 = "<color=#ffd34c>目前，城市中心区域的侵蚀波密度正在逐渐上升。</color>"
L45_1.m_Talk_SCN = L46_1
L46_1 = "<color=#ffd34c>Die Dichte der Verderbniswellen im Stadtzentrum nimmt kontinuierlich zu.</color>"
L45_1.m_Talk_DEU = L46_1
L46_1 = "<color=#ffd34c>La densité des rayons de corruption augmente progressivement au centre-ville.</color>"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP1_ACT1_STAGE1_START@233#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 7
L46_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "TUTORIAL_VOICE_48"
L46_1.m_VoiceFileName = L47_1
L47_1 = "<color=#ffd34c>현재의 추세로 볼 때, 곧 카운터사이드 이펙트 경보가 발령될 예정입니다.</color>"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "<color=#ffd34c>現在の状況から、まもなくCSE（カウンターサイドエフェクト）警報が発令される見込みです。</color>"
L46_1.m_Talk_JPN = L47_1
L47_1 = "<color=#ffd34c>Given the current trend, a Counterside Effect alert may be issued soon.</color>"
L46_1.m_Talk_ENG = L47_1
L47_1 = "<color=#ffd34c>觀察目前情況，很快就會發布異界效果警報。</color>"
L46_1.m_Talk_TWN = L47_1
L47_1 = "<color=#ffd34c>ถ้าสถานการณ์ยังเป็นแบบนี้ต่อไป\nคาดว่าเราจะต้องออกประกาศเตือนปรากฏการณ์เคาน์เตอร์ไซด์ในไม่ช้า</color>"
L46_1.m_Talk_THA = L47_1
L47_1 = "<color=#ffd34c>Theo tình trạng hiện nay, có thể sẽ sớm ban hành cảnh báo Hiệu Ứng Counterside.</color>"
L46_1.m_Talk_VTN = L47_1
L47_1 = "<color=#ffd34c>根据目前趋势预测，将立刻发布异界效应警报。</color>"
L46_1.m_Talk_SCN = L47_1
L47_1 = "<color=#ffd34c>Bleibt es bei dieser Entwicklung, wird bald Counterside-Effekt-Alarm gegeben.</color>"
L46_1.m_Talk_DEU = L47_1
L47_1 = "<color=#ffd34c>Vu la tendance actuelle, il est probable qu'une alerte aux effets du Contremonde soit imminente.</color>"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP1_ACT1_STAGE1_START@234#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 7
L47_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "TUTORIAL_VOICE_49"
L47_1.m_VoiceFileName = L48_1
L48_1 = "<color=#ffd34c>민간인은 현장을 통제하는 태스크포스의 지시에 따라 즉각 대피하시기 바랍니다.</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "<color=#ffd34c>市民の皆様は、現場を統制するタスクフォースカンパニーの指示に従ってただちに避難してください。</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "<color=#ffd34c>Please follow the instructions of the TASKFORCE companies onsite and evacuate as quickly as possible.</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "<color=#ffd34c>請平民立刻依照現場特遣勢力的指示進行疏散。</color>"
L47_1.m_Talk_TWN = L48_1
L48_1 = "<color=#ffd34c>โปรดปฏิบัติตามคำสั่งของบริษัททาสก์ฟอร์สในพื้นที่และอพยพโดยเร็วที่สุด</color>"
L47_1.m_Talk_THA = L48_1
L48_1 = "<color=#ffd34c>Hãy làm theo hướng dẫn của các công ty TASKFORCE tại chỗ và sơ tán nhanh nhất có thể.</color>"
L47_1.m_Talk_VTN = L48_1
L48_1 = "<color=#ffd34c>普通市民请立即按照控制现场的特遣势力的指示进行躲避。</color>"
L47_1.m_Talk_SCN = L48_1
L48_1 = "<color=#ffd34c>Bitte befolgen Sie die Anweisungen der TASKFORCE-Unternehmen vor Ort und verlassen Sie die Innenstadt schnellstmöglich.</color>"
L47_1.m_Talk_DEU = L48_1
L48_1 = "<color=#ffd34c>Veuillez suivre les instructions des entreprises TASKFORCE et évacuer les lieux au plus vite.</color>"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
