L50_1 = "EP1_ACT1_STAGE1_START@236#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 7
L49_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "TUTORIAL_VOICE_50"
L49_1.m_VoiceFileName = L50_1
L49_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L50_1 = "어머, 큰일이네. 하필 이럴 때……."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "困りますね。よりによってこんな時に……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Oh geez, not now."
L49_1.m_Talk_ENG = L50_1
L50_1 = "天啊！真是的，怎麼偏偏挑這種時候……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ให้ตายสิ ทำไมต้องตอนนี้ด้วย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ôi trời, không phải bây giờ chứ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "哎呀，糟了，偏偏在这个时候……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Oh Mann, nicht jetzt."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Oh non, pas maintenant."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP1_ACT1_STAGE1_START@237#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 7
L50_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "TUTORIAL_VOICE_51"
L50_1.m_VoiceFileName = L51_1
L50_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L51_1 = "죄송합니다, 사장님. 아무래도 도착이 늦어질 것 같네요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "申し訳ございません、社長。どうやら到着が遅れてしまいそうです。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I'm sorry, Boss. I'm afraid we can't get to the office quickly."
L50_1.m_Talk_ENG = L51_1
L51_1 = "老闆很抱歉，看來我們無法準時到公司了！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ขอโทษนะคะ บอส เกรงว่าเราคงรีบไปถึงสำนักงานไม่ได้แล้วล่ะค่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi xin lỗi, Ông Chủ. Tôi lo là chúng ta không thể đến văn phòng nhanh đâu."
L50_1.m_Talk_VTN = L51_1
L51_1 = "对不起，老板。看来得晚一点才能到公司了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Tut mir leid, Boss. Ich fürchte, so schnell kommen wir nicht ins Büro."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Désolée, monsieur. Je crois que nous n'arriverons pas au bureau de sitôt."
L50_1.m_Talk_FRA = L51_1
