L2_1 = "EP1_ACT1_STAGE1_START@238#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 7
L1_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "TUTORIAL_VOICE_52"
L1_1.m_VoiceFileName = L2_1
L1_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L2_1 = "부사장님께 연락을 드리려고 하는데, 혹시 지시하실 사항이나 전언이 있으신가요?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "副社長に連絡しようと思いますが、他に指示や伝言などはございませんか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I should contact the Vice President. Is there anything you'd like to tell her?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "我會先跟副總報告一聲，老闆有什麼需要通知或交代副總的嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันควรติดต่อรองประธาน มีอะไรที่อยากฝากบอกเธอมั้ยคะ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi nên liên lạc với Phó Chủ Tịch. Ngài có muốn nói gì với cô ấy không?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "我要联系一下副总，您有什么指示或口信要转达的吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich sollte der Vizevorsitzenden Bescheid sagen. Soll ich ihr etwas ausrichten?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je ferais bien d'appeler la vice-présidente. Voudriez-vous lui dire quelque chose ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
