L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 7
L3_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L3_1.m_bWaitClick = false
L3_1.m_fWaitTime = 0
L4_1 = "m_Action"
L5_1 = "SELECT"
L3_1[L4_1] = L5_1
L4_1 = "m_ActionStrKey"
L5_1 = "MARK5"
L3_1[L4_1] = L5_1
L4_1 = "요인을 구출해 달라고 전해 주게."
L3_1.m_Talk_KOREA = L4_1
L4_1 = "要人を救出してほしいと伝えてくれ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Please tell her to rescue the VIP."
L3_1.m_Talk_ENG = L4_1
L4_1 = "轉告副總，務必救出要員。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "บอกให้เธอช่วย VIP ด้วยนะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hãy nói với cô ấy giải cứu VIP?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "告诉她这里有“重要人员”需要营救。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ja. Sie soll den VIP retten."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Dites-lui de sauver le VIP."
L3_1.m_Talk_FRA = L4_1
