L7_1 = "EP1_ACT1_STAGE1_START@243#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 7
L6_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "TUTORIAL_VOICE_55"
L6_1.m_VoiceFileName = L7_1
L6_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L7_1 = "알겠습니다. 부사장님께도 바로 연락드리겠습니다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "承知しました。副社長にすぐ連絡を入れます。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Yes, sir. I'll contact the Vice President right away."
L6_1.m_Talk_ENG = L7_1
L7_1 = "收到，我馬上通知副總。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ได้ค่ะ ฉันจะติดต่อรองประธานทันที"
L6_1.m_Talk_THA = L7_1
L7_1 = "Vâng, thưa ngài. Tôi sẽ liên lạc với Phó Chủ Tịch ngay."
L6_1.m_Talk_VTN = L7_1
L7_1 = "好的，我马上联系副总。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ja, Sir. Ich werde die Vizevorsitzende sofort kontaktieren."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Bien, monsieur. J'appelle la vice-présidente tout de suite."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP1_ACT1_STAGE1_START@244#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 7
L7_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "TUTORIAL_VOICE_56"
L7_1.m_VoiceFileName = L8_1
L7_1.m_CharStrID = "KIMHANA_COFFIN_NULL_NULL"
L8_1 = "아, 요인의 인상착의와 위치는 어떻게 전달할까요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あ、要人の顔つきや服装、場所についてはどう伝えますか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Oh, and what should I tell her about this VIP, as far as his appearance and location go?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過，要員的穿著長相和位置要怎麼說啊？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ว่าแต่ฉันควรจะบอกอะไรเธอเรื่อง VIP คะ เช่น เขาหน้าตาแบบไหน อยู่ที่ไหน?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ồ, tôi nên nói gì với cô ấy về vị VIP này, ví dụ như ngoại hình và địa điểm mà anh ta tới chẳng hạn?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "啊，需要对要员的衣着相貌和位置信息进行具体说明么？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Oh – und was soll ich ihr sagen, wie dieser VIP aussieht und wo er sich befindet?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oh, et que dois-je lui dire à propos de ce VIP ? À quoi ressemble-t-il, où se trouve-t-il ?"
L7_1.m_Talk_FRA = L8_1
