L17_1 = "EP1_ACT1_STAGE1_START@6#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 7
L16_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "m_bTitleClear"
L16_1[L17_1] = true
L16_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE"
L17_1 = "TUTORIAL_VOICE_57"
L16_1.m_VoiceFileName = L17_1
L17_1 = "<color=#ffd34c>그라운드 원, 도시관리국에서 알려드립니다.</color>"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "<color=#ffd34c>グラウンド・ワン、都市管理局からのお知らせです。</color>"
L16_1.m_Talk_JPN = L17_1
L17_1 = "<color=#ffd34c>This is an announcement from Ground One, City Managements.</color>"
L16_1.m_Talk_ENG = L17_1
L17_1 = "<color=#ffd34c>Ground 1，傳達城市管理局通知。</color>"
L16_1.m_Talk_TWN = L17_1
L17_1 = "<color=#ffd34c>นี่คือประกาศจากสำนักบริหารเมือง กราวด์วัน</color>"
L16_1.m_Talk_THA = L17_1
L17_1 = "<color=#ffd34c>Đây là thông báo từ Cơ Sở Một, Cục Quản Lý Thành Phố.</color>"
L16_1.m_Talk_VTN = L17_1
L17_1 = "<color=#ffd34c>由第一区域城市管理局转达通知。</color>"
L16_1.m_Talk_SCN = L17_1
L17_1 = "<color=#ffd34c>Dies ist eine Mitteilung der Stadtverwaltung von Ground One.</color>"
L16_1.m_Talk_DEU = L17_1
L17_1 = "<color=#ffd34c>Ceci est une annonce de la direction des cités du Site n°1.</color>"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP1_ACT1_STAGE1_START@7#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 7
L17_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "TUTORIAL_VOICE_58"
L17_1.m_VoiceFileName = L18_1
L18_1 = "<color=#ffd34c>현재, 도심 전역에 침식파 밀도가 서서히 증가하고 있습니다.</color>"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "<color=#ffd34c>現在、都心全域の侵食波濃度が徐々に上昇しています。</color>"
L17_1.m_Talk_JPN = L18_1
L18_1 = "<color=#ffd34c>The density of Corruption rays is gradually increasing across the city center.</color>"
L17_1.m_Talk_ENG = L18_1
L18_1 = "<color=#ffd34c>目前，城市中心區域的侵蝕波密度正在緩慢上升中。</color>"
L17_1.m_Talk_TWN = L18_1
L18_1 = "<color=#ffd34c>ขณะนี้รังสีคอร์รัปชั่นเริ่มทวีความหนาแน่นขึ้นทีละน้อยทั่วพื้นที่ใจกลางเมือง</color>"
L17_1.m_Talk_THA = L18_1
L18_1 = "<color=#ffd34c>Mật độ của Tia Ăn Mòn đang tăng dần ở trung tâm thành phố.</color>"
L17_1.m_Talk_VTN = L18_1
L18_1 = "<color=#ffd34c>当前，城市中心区域的侵蚀波密度正在缓慢上升中。</color>"
L17_1.m_Talk_SCN = L18_1
L18_1 = "<color=#ffd34c>Die Dichte der Verderbniswellen im Stadtzentrum nimmt kontinuierlich zu.</color>"
L17_1.m_Talk_DEU = L18_1
L18_1 = "<color=#ffd34c>La densité des rayons de corruption augmente progressivement dans le centre-ville.</color>"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP1_ACT1_STAGE1_START@8#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 7
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "TUTORIAL_VOICE_59"
L18_1.m_VoiceFileName = L19_1
L19_1 = "<color=#ffd34c>현재의 추세로 볼 때, 곧 카운터사이드 이펙트 경보가 발령될 예정입니다.</color>"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "<color=#ffd34c>現在の状況から、まもなくCSE（カウンターサイドエフェクト）警報が発令される見込みです。</color>"
L18_1.m_Talk_JPN = L19_1
L19_1 = "<color=#ffd34c>Given the current trend, a Counterside Effect alert may be issued soon.</color>"
L18_1.m_Talk_ENG = L19_1
L19_1 = "<color=#ffd34c>按照目前趨勢預測，管理局即將發佈異界效應警報。</color>"
L18_1.m_Talk_TWN = L19_1
L19_1 = "<color=#ffd34c>ถ้าสถานการณ์ยังเป็นแบบนี้ต่อไป\nคาดว่าเราจะต้องออกประกาศเตือนปรากฏการณ์เคาน์เตอร์ไซด์ในไม่ช้า</color>"
L18_1.m_Talk_THA = L19_1
L19_1 = "<color=#ffd34c>Theo tình trạng hiện nay, có thể sẽ sớm ban hành cảnh báo Hiệu Ứng Counterside.</color>"
L18_1.m_Talk_VTN = L19_1
L19_1 = "<color=#ffd34c>按照目前趋势预测，管理局即将发布异界效应警报。</color>"
L18_1.m_Talk_SCN = L19_1
L19_1 = "<color=#ffd34c>Bleibt es bei dieser Entwicklung, wird bald eine Counterside-Effekt-Warnung ausgegeben.</color>"
L18_1.m_Talk_DEU = L19_1
L19_1 = "<color=#ffd34c>Vu la tendance actuelle, il est probable qu'une alerte aux effets du Contremonde soit imminente.</color>"
L18_1.m_Talk_FRA = L19_1
