L23_1 = "TUTORIAL_VOICE_60"
L22_1.m_VoiceFileName = L23_1
L23_1 = "<color=#ffd34c>시민 여러분들은 안전한 장소에 머물러 주시고,</color>"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ffd34c>市民の皆様は安全な場所に避難していただき、</color>"
L22_1.m_Talk_JPN = L23_1
L23_1 = "<color=#ffd34c>All citizens are encouraged to stay in safe locations.</color>"
L22_1.m_Talk_ENG = L23_1
L23_1 = "<color=#ffd34c>請各位市民停留在安全場所，</color>"
L22_1.m_Talk_TWN = L23_1
L23_1 = "<color=#ffd34c>เราขอแนะนำให้ประชาชนทุกคนอยู่ในที่ที่ปลอดภัย</color>"
L22_1.m_Talk_THA = L23_1
L23_1 = "<color=#ffd34c>Khuyến khích tất cả công dân ở yên trong các địa điểm an toàn.</color>"
L22_1.m_Talk_VTN = L23_1
L23_1 = "<color=#ffd34c>请各位市民停留在安全场所，</color>"
L22_1.m_Talk_SCN = L23_1
L23_1 = "<color=#ffd34c>Alle Bürger werden aufgefordert, sich an sicheren Orten aufzuhalten.</color>"
L22_1.m_Talk_DEU = L23_1
L23_1 = "<color=#ffd34c>Il est recommandé à tous les citoyens de rester en lieu sûr.</color>"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP1_ACT1_STAGE1_START@13#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 7
L23_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "TUTORIAL_VOICE_61"
L23_1.m_VoiceFileName = L24_1
L24_1 = "<color=#ffd34c>관리국과 계약된 태스크포스 컴퍼니들은 각자 관리 구역으로 출동해 주시기 바랍니다.</color>"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "<color=#ffd34c>管理局と契約しているタスクフォースカンパニーは、各々の管理区域に出動してください。</color>"
L23_1.m_Talk_JPN = L24_1
L24_1 = "<color=#ffd34c>All TASKFORCE companies contracted with the Administration must mobilize at their respective administrative zones.</color>"
L23_1.m_Talk_ENG = L24_1
L24_1 = "<color=#ffd34c>也請與管理局簽約的特遣勢力公司向各自管理的區域派遣小隊。</color>"
L23_1.m_Talk_TWN = L24_1
L24_1 = "<color=#ffd34c>บริษัททาสก์ฟอร์สที่อยู่ภายใต้สัญญาจ้างองค์การบริหารโลก\nจะต้องเคลื่อนพลไปยังเขตการจัดการของตน</color>"
L23_1.m_Talk_THA = L24_1
L24_1 = "<color=#ffd34c>Tất cả các công ty TASKFORCE đã ký hợp đồng với Cục Quản Lý phải huy động lực lượng tại khu hành chính tương ứng của mình.</color>"
L23_1.m_Talk_VTN = L24_1
L24_1 = "<color=#ffd34c>也请各管理局签约特遣势力公司能向各自管理区域出动派遣小队。</color>"
L23_1.m_Talk_SCN = L24_1
L24_1 = "<color=#ffd34c>Alle TASKFORCE-Unternehmen, die bei der Administration unter Vertrag stehen, müssen in ihrem jeweiligen Verwaltungsgebiet ihre Truppen mobilisieren.</color>"
L23_1.m_Talk_DEU = L24_1
L24_1 = "<color=#ffd34c>Toutes les entreprises TASKFORCE sous contrat avec l'Administration sont priées de se déployer dans leurs zones administratives respectives.</color>"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP1_ACT1_STAGE1_START@14#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 7
L24_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "TUTORIAL_VOICE_62"
L24_1.m_VoiceFileName = L25_1
L25_1 = "<color=#ffd34c>또한 정화작전에 참여할 신규 인원들은 각자 지정 소대로 모여 등록 및 편성 절차를 마쳐 주시기 바랍니다.</color>"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "<color=#ffd34c>また、浄化作戦に参加する新規メンバーは、各自の指定小隊に合流し、登録および編成の手続きを済ませてください。</color>"
L24_1.m_Talk_JPN = L25_1
L25_1 = "<color=#ffd34c>All new operatives should register with their designated squads to complete preparations for the upcoming Purification operations.</color>"
L24_1.m_Talk_ENG = L25_1
L25_1 = "<color=#ffd34c>另外，請參與淨化作戰的新員工到指定小隊集合，完成登記及入隊手續</color>"
L24_1.m_Talk_TWN = L25_1
L25_1 = "<color=#ffd34c>เจ้าหน้าที่ใหม่ทุกคนโปรดลงทะเบียนกับหน่วยที่ตนสังกัด\nเพื่อเตรียมตัวให้พร้อมสำหรับปฏิบัติการชำระล้างที่กำลังจะมาถึง</color>"
L24_1.m_Talk_THA = L25_1
L25_1 = "<color=#ffd34c>Tất cả đặc vụ mới phải đăng ký với tiểu đội được chỉ định để hoàn tất quá trình chuẩn bị cho các chiến dịch Thanh Lọc sắp tới.</color>"
L24_1.m_Talk_VTN = L25_1
L25_1 = "<color=#ffd34c>另外，请参与净化作战的新员工到指定小队报道，完成登记及入队手续。</color>"
L24_1.m_Talk_SCN = L25_1
L25_1 = "<color=#ffd34c>Alle neuen Einsatzkräfte sollen sich bei den ihnen zugewiesenen Trupps melden, um Vorbereitungen für die bevorstehenden Läuterungseinsätze abzuschließen.</color>"
L24_1.m_Talk_DEU = L25_1
L25_1 = "<color=#ffd34c>Les nouveaux agents sont tenus de rejoindre leurs escouades attitrées pour achever les préparatifs en vue des prochaines opérations de purification.</color>"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
