L34_1 = "TUTORIAL_VOICE_66"
L33_1.m_VoiceFileName = L34_1
L34_1 = "이젠 완전히 은퇴하신 줄 알았는데요?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "もう完全に引退されたと思っていたのですが……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Didn't you retire from this line of work?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "我還以為妳已經隱退了呢。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ยังไม่วางมือจากงานแบบนี้อีกเหรอครับ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Chẳng phải người đã nghỉ hưu rồi sao?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "我还以为您已经隐退了呢，"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hast du dich nicht aus diesem Geschäft zurückgezogen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Vous n'aviez pas pris votre retraite ?"
L33_1.m_Talk_FRA = L34_1
