L38_1 = "TUTORIAL_VOICE_69"
L37_1.m_VoiceFileName = L38_1
L38_1 = "HILDE_FENRIR_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "나도 네놈이 아직 살아있을 줄은 몰랐군."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "こっちこそ、お前がまだ生きているなんて心外だな。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I'm surprised you're still alive."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你這小子竟然還活著。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "น่าแปลกใจจริงๆ ที่นายยังมีชีวิตอยู่"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ta ngạc nhiên vì cậu còn sống đấy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你小子竟然还活着，"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich bin erstaunt, dass du noch lebst."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je suis surprise de vous trouver encore en vie."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP1_ACT1_STAGE1_START@28#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 7
L38_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "TUTORIAL_VOICE_70"
L38_1.m_VoiceFileName = L39_1
L39_1 = "HILDE_FENRIR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "진작 어디서 뒈졌을 줄 알았는데."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "とっくにどこかでくたばってると思っていたが。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I thought you'd have gotten yourself killed by now."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我還以為你早在哪裡掛了呢。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "นึกว่าจะตายไปแล้วซะอีก"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ta cứ tưởng cậu đã tự giết mình từ đời nào rồi cơ."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我还以为你早在哪里挂了呢。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich dachte, du wärst mittlerweile unter die Räder gekommen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je pensais que vous vous seriez fait tuer depuis le temps."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
