L41_1 = "EP1_ACT1_STAGE1_START@30#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 7
L40_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "TUTORIAL_VOICE_72"
L40_1.m_VoiceFileName = L41_1
L41_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "오랜만에 만난 사랑스런 제자에게 하는 인사치곤 너무 살벌한데요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "久々に会えた愛弟子に、ちょっと辛口すぎませんか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Is that the first thing you say to your \"beloved apprentice\" after all this time? That's cold..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "面對許久未見的可愛徒弟，妳打招呼的方式會不會太有殺氣了一點？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เราไม่ได้เจอกันนานขนาดนี้ นี่คือคำพูดแรกที่พูดกับ \"ศิษย์รัก\"เหรอครับเนี่ย? ใจดำชะมัดเลย..."
L40_1.m_Talk_THA = L41_1
L41_1 = "Đó là câu đầu tiên người nói với \"đồ đệ yêu quý\" của mình sau từng ấy thời gian sao? Thật là lạnh lùng quá đi à..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "面对许久未见的可爱徒弟，您打招呼的方式是不是太杀气腾腾了点？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das ist das Erste, was du deinem „geliebten Lehrling“ nach all der Zeit zu sagen hast? Ganz schön kaltherzig …"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Après tant de temps, c'est tout ce que vous trouvez à dire à votre « apprenti adoré » ? C'est un peu dur..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT1_STAGE1_START@31#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 7
L41_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "TUTORIAL_VOICE_73"
L41_1.m_VoiceFileName = L42_1
L42_1 = "HILDE_FENRIR_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "사랑스런 제자가 다 얼어 죽었나......"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "なにが愛弟子だ、そんなやつはいない……"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Of course not. I just don't see any \"beloved apprentice\" here."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我可愛的徒弟全都死光了嗎……"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันไม่ได้ใจดำสักหน่อย แล้วนายก็ไม่ใช่ \"ศิษย์รัก\" ของฉันด้วย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tất nhiên là không. Chỉ là ta chẳng nhìn thấy \"đồ đệ yêu quý\" nào ở đây cả."
L41_1.m_Talk_VTN = L42_1
L42_1 = "我可爱的徒弟全都死光了吗……"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Natürlich nicht – aber ich sehe hier keinen „geliebten Lehrling“."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Bien sûr que non. C'est juste que je ne vois aucun « apprenti adoré » ici."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP1_ACT1_STAGE1_START@32#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 7
L42_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "TUTORIAL_VOICE_74"
L42_1.m_VoiceFileName = L43_1
L43_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "부끄러워하는 모습도 나이에 안 맞게 귀여우시네요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "その照れてる姿、いくつになっても可愛いもんですね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Oh, don't be shy. Although I've got to say, you're cut for your age when you do that."
L42_1.m_Talk_ENG = L43_1
L43_1 = "與妳年紀不符的害羞模樣也很可愛喔。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "โธ่ ไม่ต้องเขินหรอกครับ แต่จะว่าไป พอเขินแล้วคุณก็ดูน่ารักสมวัยดีนะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ôi đừng ngại ngùng như thế. Mặc dù tôi phải nói là người trông trẻ ra khi làm vậy đấy."
L42_1.m_Talk_VTN = L43_1
L43_1 = "您害羞的样子也超可爱哦。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ach, sei nicht so zurückhaltend … Obwohl ich sagen muss, dass du dabei für dein Alter echt gut aussiehst."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh, ne soyez pas gênée. Mais je dois dire que, même à votre âge, la timidité vous va à ravir."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP1_ACT1_STAGE1_START@33#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 7
L43_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L43_1.m_bWaitClick = true
