L45_1 = "TUTORIAL_VOICE_76"
L44_1.m_VoiceFileName = L45_1
L45_1 = "HILDE_FENRIR_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "너랑 얘기하고 있으면 항상 머리가 아파."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "お前と話してると、いつも頭が痛くなるな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Talking to you always gives me a headache."
L44_1.m_Talk_ENG = L45_1
L45_1 = "每次和你說話就頭痛。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "คุยกับนายทีไรแล้วฉันปวดหัวทุกที"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nói chuyện với cậu lúc nào cũng khiến ta đau não."
L44_1.m_Talk_VTN = L45_1
L45_1 = "每次和你说话就头痛。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wenn ich mit dir rede, kriege ich immer Kopfschmerzen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Vous n'avez pas votre pareil pour me donner la migraine."
L44_1.m_Talk_FRA = L45_1
