L47_1.m_VoiceFileName = L48_1
L48_1 = "HILDE_FENRIR_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "뭘 그렇게 자꾸 힐끔거리는 거냐?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "なんでそんなにちらちら見るんだ？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Why do you keep looking at me like that?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "幹嘛一直盯著我看？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เอาแต่มองฉันแบบนั้น ต้องการอะไรกันแน่?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Sao cậu cứ nhìn ta như vậy thế?"
