L48_1 = "干嘛一直盯着我看？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Warum schaust du mich so an?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Pourquoi me regardez-vous comme ça ?"
L47_1.m_Talk_FRA = L48_1
