L50_1 = "EP1_ACT1_STAGE1_START@39#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 7
L49_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
