L50_1 = "TUTORIAL_VOICE_80"
L49_1.m_VoiceFileName = L50_1
L50_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "슬슬 영정사진이나 찍으러 다니셔야 할 분이......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そろそろ遺影を撮影してもおかしくないような方が……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "It's just that you're well past your prime now..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我只是有些好奇，某些差不多該去拍遺照的人……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ผมแค่คิดว่า ตอนนี้มันเลยยุครุ่งเรืองของคุณมานานแล้ว..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Chỉ là giờ người đã vượt qua được quá khứ của mình rồi nhỉ..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "我只是有些好奇，某些差不多该去拍遗照的人……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Es ist nur so, dass du deine besten Jahre längst hinter dir hast."
L49_1.m_Talk_DEU = L50_1
L50_1 = "C'est juste que vous n'êtes plus de première jeunesse..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP1_ACT1_STAGE1_START@40#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 7
L50_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "TUTORIAL_VOICE_81"
L50_1.m_VoiceFileName = L51_1
L51_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "굳이 여기까지 행차하신 진짜 이유가 뭘까 궁금해서요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "わざわざここまでお出ましになった本当の理由は何かな、と考えてまして。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "So I'm curious about the real reason you bothered to show up here."
L50_1.m_Talk_ENG = L51_1
L51_1 = "出現在這裡的真正理由是什麼？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ก็เลยอยากรู้เหตุผลที่แท้จริง ที่ทำให้คุณอุตส่าห์ถ่อมาถึงนี่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nên tôi tò mò về nguyên nhân thực sự khiến người phải xuất đầu lộ diện ở đây đấy."
L50_1.m_Talk_VTN = L51_1
L51_1 = "跑到这里来的真正理由是什么呢？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Deshalb bin ich gespannt auf den wahren Grund, der dich dazu bewogen hat, hier aufzutauchen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Alors je me demande quelle est la véritable raison de votre présence ici."
L50_1.m_Talk_FRA = L51_1
