L8_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "몇 년씩이나 무소식이던 분이 예고도 없이 나타나셨는데......."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "何年も音沙汰なしだったのに、何の前触れもなく突然現れて……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "It's just that I haven't heard from you for years, and then you happen to show up unannounced..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "一個幾年間一點消息都沒有的人毫無預警地出現了……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่ผมไม่ได้ข่าวคุณมาหลายปี แล้วจู่ๆ คุณก็โผล่มาโดยที่ไม่บอกใครเลย..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Chỉ là tôi đã không nghe tin tức gì về người trong nhiều năm rồi, sau đó người lại tình cờ xuất hiện không báo trước ở đây..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "一个几年间一点消息都没有的人，不声不响地又出现了……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Es ist nur so, dass ich jahrelang nichts von dir gehört habe. Und dann tauchst du plötzlich überraschend auf."
L7_1.m_Talk_DEU = L8_1
L8_1 = "C'est juste que vous êtes restée sans donner de nouvelles pendant des années, et que vous débarquez sans crier gare..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP1_ACT1_STAGE1_START@48#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 7
L8_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "TUTORIAL_VOICE_89"
L8_1.m_VoiceFileName = L9_1
L9_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "그날이 하필 신입사원이 들어오는 날이라니."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それがたまたま新入社員の入社日だった。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "And that happens to be the day the new recruit is coming in."
L8_1.m_Talk_ENG = L9_1
L9_1 = "而且還剛好是在新員工到來的這天。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แถมยังมาในวันที่เรารับเด็กใหม่นั่นเข้าทำงานอีก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Và lại còn đúng vào ngày tân binh mới đến nữa chứ."
L8_1.m_Talk_VTN = L9_1
L9_1 = "还正巧是在新入职员到来的那天，"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Und das zufällig an dem Tag, an dem die neue Rekrutin eintrifft."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Alors que la nouvelle recrue arrive précisément aujourd'hui."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP1_ACT1_STAGE1_START@49#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 7
L9_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "TUTORIAL_VOICE_90"
L9_1.m_VoiceFileName = L10_1
L10_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "물론 이 모든 건 놀라운 우연일 뿐이겠죠, 하하."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "もちろん、すべては驚くべき偶然の賜物ですよね、ハハハ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Of course, this might all just be a wild coincidence! Haha."
L9_1.m_Talk_ENG = L10_1
L10_1 = "這一切當然都只是令人驚訝的巧合而已啦，哈哈。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แน่นอนว่ามันอาจจะเป็นเรื่องบังเอิญสุดๆ ก็ได้! ฮะฮะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tất nhiên, những chuyện này có thể chỉ là tình cờ thôi! Haha."
L9_1.m_Talk_VTN = L10_1
L10_1 = "所有的这一切，当然都只是令人惊讶的巧合而已啦，哈哈。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Klar, das kann natürlich alles nur Zufall sein, haha."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Bien sûr, tout ceci n'est peut-être qu'une formidable coïncidence ! Ha ha."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP1_ACT1_STAGE1_START@50#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 7
L10_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "TUTORIAL_VOICE_91"
L10_1.m_VoiceFileName = L11_1
L11_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "......바보도 안 믿을 정도로."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "……バカでも信じないと思いますが。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "...But even an idiot could connect the dots."
L10_1.m_Talk_ENG = L11_1
L11_1 = "……雖然是個連傻子都不會相信的巧合。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "...แต่อะไรๆ มันชัดเจนขนาดนี้ ต่อให้เป็นคนโง่แค่ไหนก็มองออก"
L10_1.m_Talk_THA = L11_1
L11_1 = "...Nhưng ngay cả một thằng ngốc cũng nhìn ra được đấy."
L10_1.m_Talk_VTN = L11_1
L11_1 = "……虽说是连傻子都不会相信的巧合呢。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "… Aber selbst ein Idiot würde Zusammenhänge erkennen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "... Mais même un idiot peut faire le lien."
L10_1.m_Talk_FRA = L11_1
