L13_1 = "EP1_ACT1_STAGE1_START@52#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 7
L12_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "TUTORIAL_VOICE_93"
L12_1.m_VoiceFileName = L13_1
L13_1 = "HILDE_FENRIR_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "그 혓바닥은 침식체 놈들이 잘라 가지도 않나?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "お前のその舌を侵食体に引っこ抜いてもらったほうがいいんじゃないか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Too bad those Corrupted Objects didn't shut you up after all these years."
L12_1.m_Talk_ENG = L13_1
L13_1 = "話這麼多，你的舌頭還沒被侵蝕體切掉嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แย่ชะมัด ผ่านมาตั้งหลายปีแล้ว พวกวัตถุคอร์รัปต์ก็ยังหุบปากนายไม่ได้สักที"
L12_1.m_Talk_THA = L13_1
L13_1 = "Trong mấy năm qua, sao cái đám Đối Tượng Bị Ăn Mòn đó không làm cậu câm họng được nhỉ."
L12_1.m_Talk_VTN = L13_1
L13_1 = "话这么多，你这舌头还没被侵蚀体切掉吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Schade, dass die Counterside-Objekte dich nach all den Jahren nicht das Schweigen gelehrt haben."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Après tant d'années, quel dommage que les objets corrompus n'aient pas réussi à vous faire taire."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
