L15_1 = "EP1_ACT1_STAGE1_START@54#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 7
L14_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "TUTORIAL_VOICE_95"
L14_1.m_VoiceFileName = L15_1
L15_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "하하, 요즘 침식체들이 근성이 부족해서 말이죠."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ハハ、最近の侵食体は根性が足りないので無理かと。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Haha! The Corrupted Objects aren't doing so well these days."
L14_1.m_Talk_ENG = L15_1
L15_1 = "哈哈，最近的侵蝕體都沒什麼骨氣啦。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฮ่าฮ่า! วัตถุคอร์รัปต์น่ะ ไม่ได้แอ้มผมง่ายๆ หรอกนะครับ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Haha! Lũ Đối Tượng Bị Ăn Mòn đó dạo này sống không yên ổn cho lắm đâu."
L14_1.m_Talk_VTN = L15_1
L15_1 = "哈哈，最近的侵蚀体都没什么骨气啦。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Haha! Den Counterside-Objekten geht es derzeit nicht besonders."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ha ha ! Les objets corrompus ne sont pas en grande forme ces jours-ci."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP1_ACT1_STAGE1_START@55#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 7
L15_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "TUTORIAL_VOICE_96"
L15_1.m_VoiceFileName = L16_1
L16_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "뭐, 혹시라도 그런 날이 오면 스승님께 제일 먼저 연락드릴게요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ま、そんな時が来たら、真っ先に師匠に連絡しますよ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But if that day ever comes, you'll be the first I break the news to."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不過，如果哪天我真的被侵蝕體切掉了舌頭，我第一個就會通知師父。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แต่ถ้าวันนั้นมาถึงจริงๆ ผมจะรีบบอกข่าวให้คุณรู้เป็นคนแรกเลย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Nhưng nếu ngày đó đến, người sẽ là người đầu tiên tôi báo tin đấy."
L15_1.m_Talk_VTN = L16_1
L16_1 = "如果哪天真的被侵蚀体切掉了舌头，我第一个就会通知老师哦。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Aber sollte es je so weit kommen, wirst du es als Erste erfahren."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mais si les choses venaient à changer, vous seriez la première à être prévenue."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
