L19_1 = "EP1_ACT1_STAGE1_START@58#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 7
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "TUTORIAL_VOICE_97"
L18_1.m_VoiceFileName = L19_1
L19_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "그나저나 자료를 보니 경력이 꽤 재미있는 아가씨더라고요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "それはそうと、資料を見る限り、なかなか面白い経歴の持ち主のようですね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Anyway, I saw the girl's files. It seems like she's got a pretty interesting history."
L18_1.m_Talk_ENG = L19_1
L19_1 = "不說這些了。我看過資料，新人是位經歷非常有趣的女性呢。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ว่าแต่ ผมอ่านแฟ้มข้อมูลของเด็กผู้หญิงคนนั้นแล้วนะครับ ประวัติของเธอน่าสนใจเลยล่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "À mà tôi đã thấy cô gái đó bay lượn rồi. Xem ra cô ấy có một lịch sử khá là thú vị đấy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "不说这些了。我看过资料了，新人是位经历非常有趣的小姐姐哦。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wie auch immer, ich habe die Akten des Mädchens gesehen. Sie scheint eine interessante Geschichte zu haben."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Enfin bref, j'ai vu le dossier de la fille. Son histoire semble plutôt intéressante."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP1_ACT1_STAGE1_START@59#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 7
L19_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "TUTORIAL_VOICE_98"
L19_1.m_VoiceFileName = L20_1
L20_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "카운터 자격평가는 관리국 기준으로 C급."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "カウンター資格評価は、管理局基準でC級。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "She's only a Grade C Counter, based on the Administration's criteria."
L19_1.m_Talk_ENG = L20_1
L20_1 = "制裁者資格評價以管理局的標準來說是C級，"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ตามเกณฑ์ขององค์การบริหารโลกแล้ว เธอเป็นแค่เคาน์เตอร์เกรด C เท่านั้น"
L19_1.m_Talk_THA = L20_1
