L23_1 = "Despite that, she's already been through two other companies."
L22_1.m_Talk_ENG = L23_1
L23_1 = "就這個水準，她來我們公司之前已經換過兩個地方了。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่ถึงอย่างนั้น เธอก็เคยทำงานกับบริษัทอื่นมาแล้ว 2 แห่ง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Mặc dù vậy, cô ấy đã làm việc cho hai công ty khác rồi."
