L31_1 = "TUTORIAL_VOICE_109"
L30_1.m_VoiceFileName = L31_1
L31_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "이렇게 펜릴 소대에 어울리는 인재가 있었다니."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ここまでフェンリル小隊にピッタリな人材がいたとは。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Sounds like a match made in heaven for the Fenrir Squad!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "沒想到有這麼適合芬里爾小隊的人才呢。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "นี่คือคนที่ฟ้าประทานมาให้หน่วยเฟนเรียร์ชัดๆ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nghe như cô ấy được sinh ra vì Tiểu Đội Fenrir vậy đó!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "没想到有这么适合芬里尔小队的人才呢。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Klingt nach genau der richtigen Kombination für den Fenrir-Trupp!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Une recrue idéale pour l'escouade Fenrir !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP1_ACT1_STAGE1_START@71#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 7
L31_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
