L32_1 = "TUTORIAL_VOICE_110"
L31_1.m_VoiceFileName = L32_1
L32_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "전 스승님이 어디서 나이라도 속이고 다니는 게 아닌가 의심했다니까요?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "てっきり、師匠がどこかで年齢詐称でもしてるんじゃないかと思いましたよ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I swear, I thought it was you on this application!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "我都在懷疑這是不是師父謊報年齡的工作履歷了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ให้สาบานก็ได้ ตอนอ่านครั้งแรกผมยังนึกว่าเป็นประวัติคุณฮิลเด้ด้วยซ้ำ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi thề là tôi đã nghĩ đến người khi đọc đơn ứng cử này!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "我都怀疑这是不是老师谎报年龄后的工作履历了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "So eine Bewerbung hätte auch von dir kommen können!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je vous assure, j'ai même cru que c'était votre propre candidature !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP1_ACT1_STAGE1_START@72#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 7
L32_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "TUTORIAL_VOICE_111"
L32_1.m_VoiceFileName = L33_1
L33_1 = "HILDE_FENRIR_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "......대체 그런 건 어디서 주워듣고 다니는 거냐?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "……いったいどこで、そんなネタを漁ってくるんだ？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "...Where did you get all that?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "……你到底是從哪裡得到這些資訊的？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "...นายไปเอาเอกสารพวกนั้นมาจากไหน?"
L32_1.m_Talk_THA = L33_1
L33_1 = "...Cậu lấy tất cả những thứ này từ đâu vậy hả?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "……你到底是从哪里听来这些的？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "… Woher hast du das alles?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "... Comment avez-vous obtenu tout cela ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE1_START@73#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 7
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "TUTORIAL_VOICE_112"
L33_1.m_VoiceFileName = L34_1
L34_1 = "HILDE_FENRIR_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "인사정보는 대외비일 텐데."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "人事情報は機密だろう？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Employee profiles are supposed to be confidential."
L33_1.m_Talk_ENG = L34_1
L34_1 = "人事資訊不是對外保密的嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ข้อมูลพนักงานควรจะเป็นความลับไม่ใช่รึไง"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hồ sơ nhân viên là thông tin tuyệt mật cơ mà."
L33_1.m_Talk_VTN = L34_1
L34_1 = "人事信息不是对外保密的吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Mitarbeiterprofile sollten eigentlich vertraulich sein."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Les fiches des employés sont censées être confidentielles."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE1_START@74#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 7
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "TUTORIAL_VOICE_113"
L34_1.m_VoiceFileName = L35_1
L35_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "관리부의 하나 씨에게 소개팅 한 건 해 주기로 하고 부탁 좀 했죠."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "管理部のスズカさんに、良い人を紹介するといってお願いしたんですよ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I introduced my friend to Hana at the Managerial Department, and then I asked her for a little favor."
L34_1.m_Talk_ENG = L35_1
L35_1 = "因為之前我幫管理部的金荷娜小姐介紹聯誼對象，所以她就幫了我一個小忙。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คุณฮานาจากแผนกบริหารเขาอยากหาเพื่อนคุยน่ะครับ ผมก็เลยแนะนำเพื่อนผมไป แลกกับการขอให้เธอช่วยนิดหน่อย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi giới thiệu bạn mình cho cô Hana ở Bộ Phận Quản Lý ấy, sau đó tôi có nhờ vả cô ấy một tí xíu."
L34_1.m_Talk_VTN = L35_1
L35_1 = "这不是之前帮管理部的千夜小姐介绍对象了嘛，所以拜托她帮了我一个小忙。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich habe Hana in der Führungsabteilung meinem Freund vorgestellt und sie dann um einen kleinen Gefallen gebeten."
L34_1.m_Talk_DEU = L35_1
L35_1 = "J'ai présenté un ami à Hana, de la Direction, puis je lui ai demandé une petite faveur."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP1_ACT1_STAGE1_START@75#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 7
L35_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "TUTORIAL_VOICE_114"
L35_1.m_VoiceFileName = L36_1
L36_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "앞으로 동료가 될지도 모를 사람이니까요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "これから仲間になるかもしれない人ですからね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I had to check her out, since she could end up being my colleague."
L35_1.m_Talk_ENG = L36_1
L36_1 = "畢竟之後說不定會變成同事，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ในเมื่อเด็กคนนี้อาจจะมาเป็นเพื่อนร่วมงานของผม ผมก็จำเป็นต้องตรวจสอบประวัติสักหน่อย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi phải kiểm tra chứ, cô ấy có thể trở thành đồng nghiệp của tôi mà."
L35_1.m_Talk_VTN = L36_1
L36_1 = "毕竟之后说不定会变成同事，"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich wollte die Neue überprüfen, da sie meine Kollegin werden könnte."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Il fallait que j'en apprenne plus sur elle, puisqu'elle pourrait devenir ma collègue."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT1_STAGE1_START@76#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 7
L36_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "TUTORIAL_VOICE_115"
L36_1.m_VoiceFileName = L37_1
L37_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "원만한 회사 생활을 위해서라도 미리미리 알아 둬야 하는 거 아니겠습니까?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "円満な関係を築くためにも、早めに調べておかないと。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "It's important to know these things to keep the company running smoothly. Don't you agree?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "就當作是為了之後融洽的公司生活嘛，應該要早點瞭解一下她呀。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เราจำเป็นต้องรู้ข้อมูลพวกนี้เอาไว้ เพื่อให้งานของบริษัทดำเนินไปอย่างราบรื่น จริงมั้ยล่ะครับ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Biết được những thông tin này là rất quan trọng, để giữ cho công ty hoạt động được trơn tru. Người không đồng ý với tôi sao?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "就算是为了之后融洽的公司生活，也应该早点了解一下她呀。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Es ist wichtig, solche Dinge zu wissen, damit das Unternehmen reibungslos funktioniert, findest du nicht auch?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Il est important de connaître ce genre de choses pour s'assurer du bon fonctionnement de l'entreprise. Vous n'êtes pas d'accord ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP1_ACT1_STAGE1_START@77#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 7
L37_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "TUTORIAL_VOICE_116"
L37_1.m_VoiceFileName = L38_1
L38_1 = "HILDE_FENRIR_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "......그런 걸 세간에서는 스토킹이라고 한단다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "……そういうのを巷ではストーカーって言わないか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "...Some might call it \"stalking\"."
L37_1.m_Talk_ENG = L38_1
L38_1 = "……你這種行為在社會上被稱作跟蹤狂。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "...ฉันว่ามันเหมือนพวกโรคจิต \"สตอล์กเกอร์\" มากกว่านะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "...Một vài người coi việc này là \"rình mò\" đấy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "……听说做这种事的人，一般被称作跟踪狂。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "… Einige Leute nennen so etwas „Stalking“."
L37_1.m_Talk_DEU = L38_1
L38_1 = "... Certains pourraient appeler cela du « harcèlement »."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
