L41_1 = "TUTORIAL_VOICE_117"
L40_1.m_VoiceFileName = L41_1
L41_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "가능하면 제 취향의 미소녀였으면 좋겠는데 말이죠."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "できれば、僕好みの美少女なら、なお良いんですけどね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I hope she's cute. That's all I'm gonna say."
L40_1.m_Talk_ENG = L41_1
L41_1 = "可以的話，希望她是我喜歡的美少女類型。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ขอให้เธอเป็นผู้หญิงที่น่ารักด้วยเถอะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Hy vọng cô ấy dễ thương. Tôi chỉ muốn nói thế thôi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "可以的话，希望她是我喜欢的美少女类型呢。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ich hoffe, sie ist süß … Mehr will ich dazu nicht sagen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "J'espère qu'elle est mignonne. C'est tout ce que j'ai à dire."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT1_STAGE1_START@81#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 7
L41_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
