L42_1 = "TUTORIAL_VOICE_118"
L41_1.m_VoiceFileName = L42_1
L42_1 = "HILDE_FENRIR_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "제발 부탁인데, 제자야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "弟子よ、お願いだから、"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I'm begging you..."
L41_1.m_Talk_ENG = L42_1
L42_1 = "算我求你了，徒弟，"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอเถอะนะ ศิษย์รักของฉัน..."
L41_1.m_Talk_THA = L42_1
L42_1 = "Van xin cậu đấy..."
L41_1.m_Talk_VTN = L42_1
L42_1 = "算我求你了，徒弟，"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich flehe dich an …"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je vous en supplie..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP1_ACT1_STAGE1_START@82#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 7
L42_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "TUTORIAL_VOICE_119"
L42_1.m_VoiceFileName = L43_1
L43_1 = "HILDE_FENRIR_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "어디 안 보이는 곳에서 객사라도 했으면 좋겠구나."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "どこか私の目が届かないところで、野垂れ死んでくれ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Can you please just go and die somewhere?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "拜託你現在去個我看不見的地方死一死。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ช่วยไปให้พ้นๆ หน้าฉันทีได้มั้ย? จะไปตายที่ไหนก็ไป"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cậu làm ơn đi chết ở xó xỉnh nào đó giúp ta được không?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "能不能去个我看不见的地方死一死。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Kannst du dich nicht einfach irgendwo hinlegen und sterben?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Pourriez-vous simplement aller mourir ailleurs, s'il vous plaît ?"
L42_1.m_Talk_FRA = L43_1
