L13_1.m_CharStrID = L14_1
L14_1 = "다른 사람은 아무도 보이질 않는데.....?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "他の人は見当たらないけど……？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "How come no one else is here?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "為什麼我沒看到其他人啊？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ทำไมมีคนแค่นี้เองล่ะ?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Sao không còn ai khác ở đây nữa thế?"
