L14_1.m_CharStrID = L15_1
L15_1 = "설마 펜릴 소대라는 곳은 당신들 둘뿐이야?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "まさか、フェンリル小隊ってあなたたちだけなの？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Don't tell me you two are the only ones in the Fenrir Squad?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "芬里爾小隊不會只有你們兩位吧？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "อย่าบอกนะว่าหน่วยเฟนเรียร์มีพวกนายแค่ 2 คน?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đừng nói với tôi hai người là những thành viên duy nhất của Tiểu Đội Fenrir đấy nhé?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "不会芬里尔小队只有你们两个人吧？"
L14_1.m_Talk_SCN = L15_1
