L16_1.m_CharStrID = L17_1
L17_1 = "펜릴 소대는 소수 정예가 모토라서요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "フェンリル小隊は少数精鋭がモットーなんです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Fenrir is all about staying small yet elite."
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為芬里爾小隊奉行的是少數精英主義。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "พวกเราเฟนเรียร์ไม่เน้นคนเยอะ แต่เน้นคุณภาพ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Fenrir là một đội nhỏ nhưng thiện chiến."
L16_1.m_Talk_VTN = L17_1
L17_1 = "因为芬里尔小队奉行的是少数精英主义，"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Bei Fenrir herrscht das Motto: klein, aber fein."
L16_1.m_Talk_DEU = L17_1
