L23_1 = "EP1_ACT1_STAGE1_START@112#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 7
L22_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "TUTORIAL_VOICE_141"
L22_1.m_VoiceFileName = L23_1
L23_1 = "YOOMINA_FENRIR_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "미리 말해 두는데, 난 돈을 벌러 온 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "先に言っとくけど、私は金稼ぎに来たの。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I'm gonna be straight with you. I'm here for the money."
L22_1.m_Talk_ENG = L23_1
L23_1 = "話說在前頭，我是為了賺錢才來這裡的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันจะไม่อ้อมค้อมก็แล้วกัน ที่ฉันมาทำงานที่นี่ก็เพราะอยากได้เงิน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi sẽ thẳng thắn với hai người. Tôi đến đây vì tiền."
L22_1.m_Talk_VTN = L23_1
L23_1 = "话说在前头，我是为赚钱才来这里的，"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich will ganz ehrlich sein: Ich bin wegen des Geldes hier."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Je vais être franche avec vous. Je suis ici pour l'argent."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP1_ACT1_STAGE1_START@113#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 7
L23_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "TUTORIAL_VOICE_142"
L23_1.m_VoiceFileName = L24_1
L24_1 = "YOOMINA_FENRIR_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "쓸데없는 텃세 놀이에 어울려 줄 여유 따윈 없어."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "無駄な威張り合いに付き合うヒマなんてないから。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I couldn't care less about hierarchy and order."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我可沒空和你們玩什麼欺負新人之類的把戲。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉันไม่สนเรื่องยศหรือตำแหน่งอะไรทั้งนั้น"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi không quan tâm thứ bậc và mệnh lệnh gì hết."
L23_1.m_Talk_VTN = L24_1
L24_1 = "可没空和你们玩儿什么欺负新人之类的把戏，"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Dinge wie Hierarchie und Ordnung sind mir völlig schnurz."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je me moque de la hiérarchie et de la discipline."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP1_ACT1_STAGE1_START@114#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 7
L24_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "TUTORIAL_VOICE_143"
L24_1.m_VoiceFileName = L25_1
L25_1 = "YOOMINA_FENRIR_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "그러니까 둘 다 내 발목만은 잡지 않길 바래."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "だから、二人とも足を引っ張らないでよね。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "So don't even think about trying to control me."
L24_1.m_Talk_ENG = L25_1
L25_1 = "所以希望你們不要妨礙我。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เพราะฉะนั้น อย่ามาควบคุมฉัน อย่าแม้แต่จะคิด"
L24_1.m_Talk_THA = L25_1
L25_1 = "Nên đừng nghĩ đến việc điều khiển tôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "所以希望你们别来碍我的事。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Also kommt nicht auf die Idee, mich kontrollieren zu wollen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Si vous pensiez pouvoir me contrôler, laissez tomber."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP1_ACT1_STAGE1_START@115#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 7
L25_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "TUTORIAL_VOICE_144"
L25_1.m_VoiceFileName = L26_1
L26_1 = "YOOMINA_FENRIR_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "물론 잡혀 줄 생각도 없지만."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "もちろん、そうさせておくつもりもないけど。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "And don't fool yourself into thinking you can."
L25_1.m_Talk_ENG = L26_1
L26_1 = "當然，我也不會讓你們妨礙我的。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่มีใครหน้าไหนออกคำสั่งกับฉันได้ อย่าสำคัญตัวผิดล่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Và cũng đừng dại dột nghĩ rằng các người có thể làm điều đó."
L25_1.m_Talk_VTN = L26_1
L26_1 = "当然，我也不会让你们来妨碍我的。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Und macht euch nicht vor, dass ihr es könntet."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Et n'allez surtout pas croire que vous en seriez capable."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP1_ACT1_STAGE1_START@116#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 7
