L28_1 = "EP1_ACT1_STAGE1_START@117#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 7
L27_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "TUTORIAL_VOICE_146"
L27_1.m_VoiceFileName = L28_1
L28_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "스승님. 저 반해 버릴 것 같아요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "師匠、僕は今すぐ惚れちゃいそうです……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Master. I think I'm in love..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "師父，我好像快要喜歡上她了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อาจารย์ครับ ผมว่าผมตกหลุมรักเข้าให้แล้วล่ะ..."
L27_1.m_Talk_THA = L28_1
L28_1 = "Sếp. Tôi nghĩ là mình yêu rồi..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "老师，我好像要喜欢上她了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Meisterin … Ich glaube, ich bin verliebt …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Maître. Je crois que je suis amoureux..."
L27_1.m_Talk_FRA = L28_1
