L31_1 = "TUTORIAL_VOICE_147"
L30_1.m_VoiceFileName = L31_1
L31_1 = "<color=#ffd34c>작전부에서 알려 드립니다.</color>"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "<color=#ffd34c>作戦部からお知らせします。</color>"
L30_1.m_Talk_JPN = L31_1
L31_1 = "<color=#ffd34c>This is an announcement from the Operation Department.</color>"
L30_1.m_Talk_ENG = L31_1
L31_1 = "<color=#ffd34c>來自作戰部的通知，</color>"
L30_1.m_Talk_TWN = L31_1
L31_1 = "<color=#ffd34c>นี่คือประกาศจากแผนกปฏิบัติการ</color>"
L30_1.m_Talk_THA = L31_1
L31_1 = "<color=#ffd34c>Đây là thông báo từ Bộ Phận Điều Hành.</color>"
L30_1.m_Talk_VTN = L31_1
L31_1 = "<color=#ffd34c>由作战部传来通知，</color>"
L30_1.m_Talk_SCN = L31_1
L31_1 = "<color=#ffd34c>Dies ist eine Bekanntgabe der Einsatzabteilung.</color>"
L30_1.m_Talk_DEU = L31_1
L31_1 = "<color=#ffd34c>Ceci est une annonce du département des opérations.</color>"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP1_ACT1_STAGE1_START@121#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 7
L31_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "TUTORIAL_VOICE_148"
L31_1.m_VoiceFileName = L32_1
L32_1 = "<color=#ffd34c>조금 전, 카운터사이드 이펙트 2단계 경보가 발령되었습니다.</color>"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "<color=#ffd34c>つい先ほど、CSE第2段階警報が発令されました。</color>"
L31_1.m_Talk_JPN = L32_1
L32_1 = "<color=#ffd34c>A Level 2 Counterside Effect alert has just been issued.</color>"
L31_1.m_Talk_ENG = L32_1
L32_1 = "<color=#ffd34c>不久前發佈了第二級異界效應警報。</color>"
L31_1.m_Talk_TWN = L32_1
L32_1 = "<color=#ffd34c>ขณะนี้มีการออกแจ้งเตือนปรากฏการณ์เคาน์เตอร์ไซด์ระดับ 2 แล้ว</color>"
L31_1.m_Talk_THA = L32_1
L32_1 = "<color=#ffd34c>Đã phát cảnh báo Hiệu Ứng Counterside Cấp 2.</color>"
L31_1.m_Talk_VTN = L32_1
L32_1 = "<color=#ffd34c>不久前发布了异界效应第二阶段警报。</color>"
L31_1.m_Talk_SCN = L32_1
L32_1 = "<color=#ffd34c>Soeben wurde eine Warnung wegen eines Counterside-Effekts der Stufe 2 ausgegeben.</color>"
L31_1.m_Talk_DEU = L32_1
L32_1 = "<color=#ffd34c>Une alerte d'effet du Contremonde de niveau 2 vient d'être lancée.</color>"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP1_ACT1_STAGE1_START@122#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 7
L32_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "TUTORIAL_VOICE_149"
L32_1.m_VoiceFileName = L33_1
L33_1 = "<color=#ffd34c>곧 침식정화작전이 진행될 예정입니다.</color>"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "<color=#ffd34c>まもなく侵食浄化作戦が開始される予定です。</color>"
L32_1.m_Talk_JPN = L33_1
L33_1 = "<color=#ffd34c>The Purification will begin soon.</color>"
L32_1.m_Talk_ENG = L33_1
L33_1 = "<color=#ffd34c>預定立即展開侵蝕淨化作戰。</color>"
L32_1.m_Talk_TWN = L33_1
L33_1 = "<color=#ffd34c>การชำระจะเริ่มต้นขึ้นในไม่ช้า</color>"
L32_1.m_Talk_THA = L33_1
L33_1 = "<color=#ffd34c>Thanh Lọc sẽ sớm bắt đầu.</color>"
L32_1.m_Talk_VTN = L33_1
L33_1 = "<color=#ffd34c>将马上开展净化。</color>"
L32_1.m_Talk_SCN = L33_1
L33_1 = "<color=#ffd34c>Die Läuterung wird bald beginnen.</color>"
L32_1.m_Talk_DEU = L33_1
L33_1 = "<color=#ffd34c>La purification va bientôt commencer.</color>"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE1_START@123#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 7
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "TUTORIAL_VOICE_150"
L33_1.m_VoiceFileName = L34_1
L34_1 = "<color=#ffd34c>반복합니다. 카운터사이드 이펙트 2단계 경보가 발령되었습니다.</color>"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "<color=#ffd34c>繰り返します。カウンターサイドエフェクト第2段階警報が発令されました。</color>"
L33_1.m_Talk_JPN = L34_1
L34_1 = "<color=#ffd34c>I repeat. A Level 2 Counterside Effect alert is now in effect.</color>"
L33_1.m_Talk_ENG = L34_1
L34_1 = "<color=#ffd34c>重複一次，已發佈第二級異界效應警報。</color>"
L33_1.m_Talk_TWN = L34_1
L34_1 = "<color=#ffd34c>ขอย้ำอีกครั้ง ขณะนี้การแจ้งเตือนปรากฏการณ์เคาน์เตอร์ไซด์ระดับ 2 มีผลบังคับใช้แล้ว</color>"
L33_1.m_Talk_THA = L34_1
L34_1 = "<color=#ffd34c>Tôi nhắc lại. Cảnh báo Hiệu Ứng Counterside Cấp 2 hiện đang có hiệu lực.</color>"
L33_1.m_Talk_VTN = L34_1
L34_1 = "<color=#ffd34c>重复一次，已发布异界效应第二阶段警报。</color>"
L33_1.m_Talk_SCN = L34_1
L34_1 = "<color=#ffd34c>Ich wiederhole: Warnung wegen eines Counterside-Effekts der Stufe 2.</color>"
L33_1.m_Talk_DEU = L34_1
L34_1 = "<color=#ffd34c>Je répète. Une alerte d'effet du Contremonde de niveau 2 est en cours.</color>"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE1_START@124#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 7
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "TUTORIAL_VOICE_151"
L34_1.m_VoiceFileName = L35_1
L35_1 = "HILDE_FENRIR_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "......오리엔테이션은 살아남으면 진행하는 걸로 해야겠군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "……オリエンテーションは、生き延びられたらするとしよう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "We'll have to save the rest of the orientation for later... If we make it back alive."
L34_1.m_Talk_ENG = L35_1
L35_1 = "……指南上有說只要活下來，就得加入淨化作戰吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เรื่องปฐมนิเทศเอาไว้ทีหลังก็แล้วกัน... ถ้าเรารอดกลับมาได้น่ะนะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Chúng ta phải để phần còn lại của buổi định hướng này cho lần sau rồi... Nếu chúng ta còn sống mà quay về."
L34_1.m_Talk_VTN = L35_1
L35_1 = "……新人介绍还是留到之后再说吧，如果我们这次都能活着回来的话。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Den Rest der Orientierung müssen wir uns wohl für später aufheben – falls wir lebend zurückkehren."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Nous allons devoir reporter le reste des présentations... Si nous parvenons à revenir en vie."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
