L39_1 = "TUTORIAL_VOICE_153"
L38_1.m_VoiceFileName = L39_1
L39_1 = "HILDE_FENRIR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "펜릴 소대 재편성을 완료했다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "フェンリル小隊の再編成を完了した。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Fenrir Squad is fully manned and ready to go."
L38_1.m_Talk_ENG = L39_1
L39_1 = "已完成芬里爾小隊的再編隊。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "หน่วยเฟนเรียร์คนครบแล้ว พวกเราพร้อมแล้วล่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tiểu Đội Fenrir đã đủ người và sẵn sàng chiến đấu."
L38_1.m_Talk_VTN = L39_1
L39_1 = "芬里尔小队集结完毕。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Der Fenrir-Trupp ist voll besetzt und einsatzbereit."
L38_1.m_Talk_DEU = L39_1
L39_1 = "L'escouade Fenrir est au complet et prête à partir."
L38_1.m_Talk_FRA = L39_1
