L40_1 = "EP1_ACT1_STAGE1_START@129#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 7
L39_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L39_1.m_bWaitClick = true
