L40_1 = "TUTORIAL_VOICE_154"
L39_1.m_VoiceFileName = L40_1
L40_1 = "HILDE_FENRIR_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "현 시간부로 작전지역에 돌입한다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "現刻より、作戦地域に突入する。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Proceeding to the AO now."
L39_1.m_Talk_ENG = L40_1
L40_1 = "現在開始進入作戰區域。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เดินทางเข้าพื้นที่ปฏิบัติการได้เลย"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đang xuất phát đến AO ngay lúc này."
L39_1.m_Talk_VTN = L40_1
L40_1 = "现在开始进入作战区域。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wir begeben uns ins Einsatzgebiet."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Nous nous rendons immédiatement sur la zone d'opération."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP1_ACT1_STAGE1_START@130#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 240
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 7
L40_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE"
L41_1 = "TUTORIAL_VOICE_155"
L40_1.m_VoiceFileName = L41_1
L41_1 = "<color=#ffd34c>여기는 코핀. 복귀를 환영합니다, 소대장.</color>"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "<color=#ffd34c>こちらコフィン。小隊長の復帰を歓迎します。</color>"
L40_1.m_Talk_JPN = L41_1
L41_1 = "<color=#ffd34c>This is Coffin. Welcome back, Commander.</color>"
L40_1.m_Talk_ENG = L41_1
L41_1 = "<color=#ffd34c>這裡是科芬。歡迎回來，小隊長。</color>"
L40_1.m_Talk_TWN = L41_1
L41_1 = "<color=#ffd34c>นี่คอฟฟินพูด ดีใจที่ได้เจอคุณอีกนะ ผู้บัญชาการ</color>"
L40_1.m_Talk_THA = L41_1
L41_1 = "<color=#ffd34c>Đây là Coffin. Hoan nghênh quay lại, Tổng Tư Lệnh.</color>"
L40_1.m_Talk_VTN = L41_1
L41_1 = "<color=#ffd34c>这里是科芬。欢迎回来，小队长。</color>"
L40_1.m_Talk_SCN = L41_1
L41_1 = "<color=#ffd34c>Hier Coffin. Willkommen zurück, Kommandantin.</color>"
L40_1.m_Talk_DEU = L41_1
L41_1 = "<color=#ffd34c>Ici le Coffin. Nous sommes ravis de vous revoir, commandante.</color>"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT1_STAGE1_START@131#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 241
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 7
L41_1.m_CutScenStrID = "EP1_ACT1_STAGE1_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "TUTORIAL_VOICE_156"
L41_1.m_VoiceFileName = L42_1
L42_1 = "<color=#ffd34c>좋은 사냥 되시길 바랍니다.</color>"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "<color=#ffd34c>どうか、楽しい狩りを。</color>"
L41_1.m_Talk_JPN = L42_1
L42_1 = "<color=#ffd34c>Happy hunting.</color>"
L41_1.m_Talk_ENG = L42_1
L42_1 = "<color=#ffd34c>希望您的狩獵一切順利。</color>"
L41_1.m_Talk_TWN = L42_1
L42_1 = "<color=#ffd34c>ขอให้สนุกกับการล่า</color>"
L41_1.m_Talk_THA = L42_1
L42_1 = "<color=#ffd34c>Chúc đi săn vui vẻ.</color>"
L41_1.m_Talk_VTN = L42_1
L42_1 = "<color=#ffd34c>希望您的狩猎一切顺利。</color>"
L41_1.m_Talk_SCN = L42_1
L42_1 = "<color=#ffd34c>Ich wünsche gute Jagd.</color>"
L41_1.m_Talk_DEU = L42_1
L42_1 = "<color=#ffd34c>Bonne chasse.</color>"
L41_1.m_Talk_FRA = L42_1
